  function getBonusLevelTimingUnitLabel(unit) {
    const normalized = String(unit || '').trim().toLowerCase();
    if (normalized === 'hours') return 'Часы';
    if (normalized === 'days') return 'Дни';
    if (normalized === 'months') return 'Месяцы';
    if (normalized === 'immediate') return 'Сразу';
    if (normalized === 'forever') return 'Бессрочно';
    return '';
  }

  function closeBonusLevelUnitMenus(exceptMenu = null) {
    [
      [bonusLevelActivationDelayUnitWrap, bonusLevelActivationDelayUnitTrigger, bonusLevelActivationDelayUnitMenu],
      [bonusLevelLifetimeUnitWrap, bonusLevelLifetimeUnitTrigger, bonusLevelLifetimeUnitMenu],
      [null, bonusLevelActivationDelayUnitDotsBtn, bonusLevelActivationDelayInputUnitMenu],
      [null, bonusLevelLifetimeUnitDotsBtn, bonusLevelLifetimeInputUnitMenu],
    ].forEach(([wrap, trigger, menu]) => {
      if (!menu) return;
      if (menu === exceptMenu) {
        if (wrap) wrap.classList.add('is-open');
        if (trigger) trigger.setAttribute('aria-expanded', 'true');
        return;
      }
      menu.classList.add('hidden');
      if (wrap) wrap.classList.remove('is-open');
      if (trigger) trigger.setAttribute('aria-expanded', 'false');
    });
  }

  function syncBonusLevelTimingMenuSelection(menuEl, value) {
    if (!menuEl) return;
    menuEl.querySelectorAll('.new-order-right-select-option').forEach((option) => {
      const isSelected = String(option.dataset.value || '') === String(value || '');
      option.classList.toggle('is-selected', isSelected);
      option.setAttribute('aria-selected', isSelected ? 'true' : 'false');
    });
  }

  function renderBonusLevelTimingControls(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    if (!current) return;

    const activationUnit = normalizeBonusLevelActivationUnit(current.activationDelayUnit);
    const lifetimeUnit = normalizeBonusLevelLifetimeUnit(current.lifetimeUnit);
    const activationValueMode = activationUnit !== 'immediate';
    const lifetimeValueMode = lifetimeUnit !== 'forever';

    if (bonusLevelActivationFieldWrap) {
      bonusLevelActivationFieldWrap.classList.toggle('is-value-mode', activationValueMode);
    }
    if (bonusLevelLifetimeFieldWrap) {
      bonusLevelLifetimeFieldWrap.classList.toggle('is-value-mode', lifetimeValueMode);
    }
    if (bonusLevelActivationDelayValueWrap) {
      bonusLevelActivationDelayValueWrap.classList.toggle('hidden', !activationValueMode);
    }
    if (bonusLevelLifetimeValueWrap) {
      bonusLevelLifetimeValueWrap.classList.toggle('hidden', !lifetimeValueMode);
    }
    if (bonusLevelActivationDelayUnitWrap) {
      bonusLevelActivationDelayUnitWrap.classList.toggle('hidden', activationValueMode);
    }
    if (bonusLevelLifetimeUnitWrap) {
      bonusLevelLifetimeUnitWrap.classList.toggle('hidden', lifetimeValueMode);
    }
    if (bonusLevelActivationDelayUnitDotsBtn) {
      bonusLevelActivationDelayUnitDotsBtn.classList.toggle('hidden', !activationValueMode);
    }
    if (bonusLevelLifetimeUnitDotsBtn) {
      bonusLevelLifetimeUnitDotsBtn.classList.toggle('hidden', !lifetimeValueMode);
    }

    if (bonusLevelActivationDelayValueInput) {
      bonusLevelActivationDelayValueInput.value = String(normalizeBonusLevelTimingValue(current.activationDelayValue, 0));
      bonusLevelActivationDelayValueInput.disabled = !activationValueMode || !isBonusLevelEditorActive(current.id);
    }
    if (bonusLevelLifetimeValueInput) {
      bonusLevelLifetimeValueInput.value = String(normalizeBonusLevelTimingValue(current.lifetimeValue, 0));
      bonusLevelLifetimeValueInput.disabled = !lifetimeValueMode || !isBonusLevelEditorActive(current.id);
    }

    if (bonusLevelActivationDelayUnitSelect) bonusLevelActivationDelayUnitSelect.value = activationUnit;
    if (bonusLevelLifetimeUnitSelect) bonusLevelLifetimeUnitSelect.value = lifetimeUnit;
    if (bonusLevelActivationDelayUnitText) bonusLevelActivationDelayUnitText.textContent = getBonusLevelTimingUnitLabel(activationUnit);
    if (bonusLevelLifetimeUnitText) bonusLevelLifetimeUnitText.textContent = getBonusLevelTimingUnitLabel(lifetimeUnit);
    syncBonusLevelTimingMenuSelection(bonusLevelActivationDelayUnitMenu, activationUnit);
    syncBonusLevelTimingMenuSelection(bonusLevelLifetimeUnitMenu, lifetimeUnit);
    syncBonusLevelTimingMenuSelection(bonusLevelActivationDelayInputUnitMenu, activationUnit);
    syncBonusLevelTimingMenuSelection(bonusLevelLifetimeInputUnitMenu, lifetimeUnit);

    const isEditing = isBonusLevelEditorActive(current.id);
    if (bonusLevelActivationDelayUnitTrigger) bonusLevelActivationDelayUnitTrigger.disabled = !isEditing || activationValueMode;
    if (bonusLevelLifetimeUnitTrigger) bonusLevelLifetimeUnitTrigger.disabled = !isEditing || lifetimeValueMode;
    if (bonusLevelActivationDelayUnitDotsBtn) bonusLevelActivationDelayUnitDotsBtn.disabled = !isEditing || !activationValueMode;
    if (bonusLevelLifetimeUnitDotsBtn) bonusLevelLifetimeUnitDotsBtn.disabled = !isEditing || !lifetimeValueMode;
    if (bonusLevelActivationDelayHint) bonusLevelActivationDelayHint.classList.add('hidden');
    if (bonusLevelLifetimeHint) bonusLevelLifetimeHint.classList.add('hidden');
    closeBonusLevelUnitMenus();
    if (!isEditing) closeBonusLevelUnitMenus();
  }

  function bindBonusLevelUnitSelect(triggerEl, wrapEl, menuEl, onSelect) {
    if (!triggerEl || !wrapEl || !menuEl || typeof onSelect !== 'function') return;
    triggerEl.addEventListener('click', (event) => {
      if (!isBonusLevelEditorActive()) return;
      event.preventDefault();
      event.stopPropagation();
      const willOpen = menuEl.classList.contains('hidden');
      closeBonusLevelUnitMenus();
      if (!willOpen) return;
      wrapEl.classList.add('is-open');
      menuEl.classList.remove('hidden');
      triggerEl.setAttribute('aria-expanded', 'true');
    });

    menuEl.querySelectorAll('.new-order-right-select-option').forEach((option) => {
      option.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        onSelect(String(option.dataset.value || '').trim());
        closeBonusLevelUnitMenus();
      });
    });
  }

  function bindBonusLevelInlineUnitMenu(triggerEl, menuEl, onSelect) {
    if (!triggerEl || !menuEl || typeof onSelect !== 'function') return;
    triggerEl.addEventListener('click', (event) => {
      if (!isBonusLevelEditorActive()) return;
      event.preventDefault();
      event.stopPropagation();
      const willOpen = menuEl.classList.contains('hidden');
      closeBonusLevelUnitMenus();
      if (!willOpen) return;
      menuEl.classList.remove('hidden');
      triggerEl.setAttribute('aria-expanded', 'true');
    });

    menuEl.querySelectorAll('.new-order-right-select-option').forEach((option) => {
      option.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        onSelect(String(option.dataset.value || '').trim());
        closeBonusLevelUnitMenus();
      });
    });
  }

  function buildBonusLevelRangeLines(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const rows = Array.isArray(current?.orderBonusRanges) ? current.orderBonusRanges : [];
    if (!rows.length) return [];
    return rows.map((row, index) => {
      const amount = normalizeBonusRangeAmount(row?.amount, 0);
      const nextAmount = normalizeBonusRangeAmount(rows[index + 1]?.amount, 0);
      const rangeLabel = nextAmount > amount
        ? `от ${amount.toLocaleString('ru-RU')} до ${(nextAmount - 1).toLocaleString('ru-RU')} ₽`
        : `от ${amount.toLocaleString('ru-RU')} ₽ и более`;
      return `${rangeLabel} / +${formatBonusRangePercentValue(row?.percent)}%`;
    });
  }

  function formatBonusLevelRangeSummary(level = null) {
    const lines = buildBonusLevelRangeLines(level);
    if (!lines.length) return '—';
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const rows = Array.isArray(current?.orderBonusRanges) ? current.orderBonusRanges : [];
    const firstRow = rows[0];
    const lastRow = rows[rows.length - 1];
    if (!firstRow || !lastRow) return '—';
    const minAmount = normalizeBonusRangeAmount(firstRow.amount, 0);
    const minPercent = formatBonusRangePercentValue(firstRow.percent);
    const maxPercent = formatBonusRangePercentValue(lastRow.percent);
    return `от ${minAmount.toLocaleString('ru-RU')} ₽ и выше / от ${minPercent}% до ${maxPercent}%`;
  }

  function formatBonusLevelRangeHelpText(level = null) {
    const lines = buildBonusLevelRangeLines(level);
    if (!lines.length) return 'Дополнительные бонусы за сумму заказа не настроены.';
    return lines.map((line, index) => `${index + 1}. ${line}`).join('\n');
  }

  function isReferralSystemEnabled() {
    return state.referralProgramEnabled === true;
  }

  function formatBonusLevelRequirementsHelpText() {
    const lines = [
      '1. \u0421\u0443\u043c\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u043e\u0432 - \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u043e\u0431\u0449\u0430\u044f \u0441\u0443\u043c\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u043e\u0432 \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c.',
      '2. \u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432 - \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432 \u043d\u0443\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c.',
    ];
    if (isReferralSystemEnabled()) {
      lines.push('3. \u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0451\u043d\u043d\u044b\u0435 \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u044b - \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u043e\u0432 \u043d\u0443\u0436\u043d\u043e \u043f\u0440\u0438\u0432\u0435\u0441\u0442\u0438.');
    }
    lines.push(
      '\u041f\u0443\u0441\u0442\u043e\u0439 \u0438\u043d\u043f\u0443\u0442 \u043d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f\u0445.',
      '"\u0438" - \u043d\u0443\u0436\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f.',
      '"\u0438\u043b\u0438" - \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043e\u0434\u043d\u043e \u0438\u0437 \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439.',
      '\u041f\u0435\u0440\u0438\u043e\u0434 - \u0437\u0430 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u043d\u0435\u0439 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0437\u0430\u043a\u0430\u0437\u044b; \u0435\u0441\u043b\u0438 \u043f\u0443\u0441\u0442\u043e, \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0431\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u044b.'
    );
    return lines.join('\n');
  }

  function formatBonusLevelRequirementsSummary(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const amount = normalizeBonusLevelRequirementValue(current?.requirementAmount);
    const orders = normalizeBonusLevelRequirementValue(current?.requirementOrders);
    const referrals = isReferralSystemEnabled() ? normalizeBonusLevelRequirementValue(current?.requirementReferrals) : null;
    const bonusAccrued = normalizeBonusLevelRequirementValue(current?.requirementBonusAccrued);
    const bonusRedeemed = normalizeBonusLevelRequirementValue(current?.requirementBonusRedeemed);
    const periodDays = normalizeBonusLevelRequirementValue(current?.requirementPeriodDays);
    const mode = normalizeBonusLevelRequirementMode(current?.requirementMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438';
    const referralMode = normalizeBonusLevelRequirementMode(current?.requirementReferralMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438';
    const parts = [
      amount != null ? `${amount.toLocaleString('ru-RU')} \u20bd` : null,
      orders != null ? `${orders.toLocaleString('ru-RU')} \u0437\u0430\u043a.` : null,
      referrals != null ? `${referrals.toLocaleString('ru-RU')} \u0440\u0435\u0444.` : null,
      bonusAccrued != null ? `+${bonusAccrued.toLocaleString('ru-RU')} \u0431.` : null,
      bonusRedeemed != null ? `-${bonusRedeemed.toLocaleString('ru-RU')} \u0431.` : null,
    ];
    const filledCount = parts.filter(Boolean).length;
    if (!filledCount) return '\u041d\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u043e';
    const expression = parts.filter(Boolean).join(` ${mode} `);
    return `${expression} / ${periodDays != null ? `${periodDays} \u0434\u043d.` : '\u0431\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e'}`;
  }

  function formatBonusLevelRequirementsDetailsText(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const amount = normalizeBonusLevelRequirementValue(current?.requirementAmount);
    const orders = normalizeBonusLevelRequirementValue(current?.requirementOrders);
    const referrals = isReferralSystemEnabled() ? normalizeBonusLevelRequirementValue(current?.requirementReferrals) : null;
    const bonusAccrued = normalizeBonusLevelRequirementValue(current?.requirementBonusAccrued);
    const bonusRedeemed = normalizeBonusLevelRequirementValue(current?.requirementBonusRedeemed);
    const periodDays = normalizeBonusLevelRequirementValue(current?.requirementPeriodDays);
    const mode = normalizeBonusLevelRequirementMode(current?.requirementMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438';
    const referralMode = normalizeBonusLevelRequirementMode(current?.requirementReferralMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438';
    const retentionStrategy = normalizeBonusLevelRetentionStrategy(current?.retentionStrategy);
    const retentionAmount = retentionStrategy === 'custom'
      ? normalizeBonusLevelRequirementValue(current?.retentionAmount)
      : amount;
    const retentionOrders = retentionStrategy === 'custom'
      ? normalizeBonusLevelRequirementValue(current?.retentionOrders)
      : orders;
    const retentionReferrals = isReferralSystemEnabled() && retentionStrategy === 'custom'
      ? normalizeBonusLevelRequirementValue(current?.retentionReferrals)
      : (isReferralSystemEnabled() ? referrals : null);
    const retentionBonusAccrued = retentionStrategy === 'custom'
      ? normalizeBonusLevelRequirementValue(current?.retentionBonusAccrued)
      : bonusAccrued;
    const retentionBonusRedeemed = retentionStrategy === 'custom'
      ? normalizeBonusLevelRequirementValue(current?.retentionBonusRedeemed)
      : bonusRedeemed;
    const retentionMode = retentionStrategy === 'custom'
      ? (normalizeBonusLevelRequirementMode(current?.retentionMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438')
      : mode;
    const retentionReferralMode = retentionStrategy === 'custom'
      ? (normalizeBonusLevelRequirementMode(current?.retentionReferralMode) === 'or' ? '\u0438\u043b\u0438' : '\u0438')
      : referralMode;
    const formatMoneyRequirement = (value) => value == null
      ? '\u041d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f'
      : `${value.toLocaleString('ru-RU')} \u20bd`;
    const formatCountRequirement = (value) => value == null
      ? '\u041d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f'
      : value.toLocaleString('ru-RU');
    const formatPeriod = () => periodDays == null
      ? '\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e'
      : `${periodDays.toLocaleString('ru-RU')} \u0434\u043d.`;

    const details = [
      '\u041f\u0435\u0440\u0435\u0445\u043e\u0434 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c',
      `\u0421\u0443\u043c\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u043e\u0432: ${formatMoneyRequirement(amount)}`,
      `\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432: ${formatCountRequirement(orders)}`,
      `\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432: ${formatCountRequirement(bonusAccrued)}`,
      `\u041f\u043e\u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432: ${formatCountRequirement(bonusRedeemed)}`,
    ];
    if (isReferralSystemEnabled()) {
      details.push(
        `\u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0451\u043d\u043d\u044b\u0435 \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u044b: ${formatCountRequirement(referrals)}`,
        `\u0421\u0432\u044f\u0437\u044c: ${mode} / ${referralMode}`
      );
    } else {
      details.push(`\u0421\u0432\u044f\u0437\u044c: ${mode}`);
    }
    details.push(
      `\u041f\u0435\u0440\u0438\u043e\u0434: ${formatPeriod()}`,
      '',
      '\u0423\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435 \u0443\u0440\u043e\u0432\u043d\u044f',
      `\u0422\u0438\u043f: ${retentionStrategy === 'custom' ? '\u0421\u0432\u043e\u0438' : '\u0421\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442'}`,
      `\u0421\u0443\u043c\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u043e\u0432: ${formatMoneyRequirement(retentionAmount)}`,
      `\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432: ${formatCountRequirement(retentionOrders)}`,
      `\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432: ${formatCountRequirement(retentionBonusAccrued)}`,
      `\u041f\u043e\u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432: ${formatCountRequirement(retentionBonusRedeemed)}`,
    );
    if (isReferralSystemEnabled()) {
      details.push(
        `\u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0451\u043d\u043d\u044b\u0435 \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u044b: ${formatCountRequirement(retentionReferrals)}`,
        `\u0421\u0432\u044f\u0437\u044c: ${retentionMode} / ${retentionReferralMode}`
      );
    } else {
      details.push(`\u0421\u0432\u044f\u0437\u044c: ${retentionMode}`);
    }
    details.push(`\u041f\u0435\u0440\u0438\u043e\u0434 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438: ${formatPeriod()}`);
    return details.join('\n');
  }

  function formatBonusLevelTariffPeriod(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const periodValue = normalizeBonusLevelTimingValue(current?.tariffPeriodValue, 1);
    const periodUnit = normalizeBonusLevelTariffPeriodUnit(current?.tariffPeriodUnit);
    if (periodUnit === 'forever') return '\u0431\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e';
    const unitLabel = periodUnit === 'days' ? '\u0434\u043d.' : '\u043c\u0435\u0441.';
    return `${periodValue.toLocaleString('ru-RU')} ${unitLabel}`;
  }

  function formatBonusLevelTariffSummary(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const rows = sanitizeBonusTariffRows(current?.tariffRows, {
      price: current?.tariffPrice,
      discountPercent: current?.tariffDiscountPercent,
      periodValue: current?.tariffPeriodValue,
      periodUnit: current?.tariffPeriodUnit,
    });
    const firstRow = rows[0] || {};
    const price = normalizeNumberInputValue(firstRow.price, 0);
    const discount = normalizeBonusPercentInputValue(firstRow.discountPercent, 0);
    const payWithBonus = current?.tariffPayWithBonus === true ? '\u0431\u043e\u043d\u0443\u0441\u0430\u043c\u0438: \u0434\u0430' : '\u0431\u043e\u043d\u0443\u0441\u0430\u043c\u0438: \u043d\u0435\u0442';
    const rowsText = rows.length > 1 ? ` / ${rows.length} \u043f\u043e\u0440\u043e\u0433\u0430` : '';
    return `${price.toLocaleString('ru-RU')} \u20bd / ${formatBonusLevelTariffPeriod({ tariffPeriodValue: firstRow.periodValue, tariffPeriodUnit: firstRow.periodUnit })} / \u0441\u043a\u0438\u0434\u043a\u0430: ${discount}%${rowsText} / ${payWithBonus}`;
  }

  function formatBonusLevelTariffDetailsText(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const rows = sanitizeBonusTariffRows(current?.tariffRows, {
      price: current?.tariffPrice,
      discountPercent: current?.tariffDiscountPercent,
      periodValue: current?.tariffPeriodValue,
      periodUnit: current?.tariffPeriodUnit,
    });
    const rowLines = rows.map((row, index) => (
      `${index + 1}. ${normalizeNumberInputValue(row.price, 0).toLocaleString('ru-RU')} \u20bd / ${formatBonusLevelTariffPeriod({ tariffPeriodValue: row.periodValue, tariffPeriodUnit: row.periodUnit })} / \u0441\u043a\u0438\u0434\u043a\u0430 ${normalizeBonusPercentInputValue(row.discountPercent, 0)}%`
    ));
    return [
      '\u041f\u043b\u0430\u0442\u043d\u044b\u0439 \u0442\u0430\u0440\u0438\u0444',
      ...rowLines,
      `\u041e\u043f\u043b\u0430\u0442\u0430 \u0431\u043e\u043d\u0443\u0441\u0430\u043c\u0438: ${current?.tariffPayWithBonus === true ? '\u0434\u0430' : '\u043d\u0435\u0442'}`,
    ].join('\n');
  }

  function showBonusLevelRequirementsValidationMessage(message) {
    if (typeof window.showToast === 'function') {
      window.showToast(message);
      return;
    }
    alert(message);
  }

  let bonusLevelRequirementsOutsideClickHandler = null;

  function closeBonusLevelRequirementsEditor() {
    if (bonusLevelRequirementsOutsideClickHandler) {
      document.removeEventListener('click', bonusLevelRequirementsOutsideClickHandler);
      bonusLevelRequirementsOutsideClickHandler = null;
    }
    const { backdrop } = getClientBenefitsOverlayElements();
    if (backdrop) backdrop.classList.remove('bonus-range-editor-overlay');
    window.AdminBenefitsModal?.hide();
  }

  function closeBonusLevelTariffEditor() {
    const { backdrop } = getClientBenefitsOverlayElements();
    if (backdrop) backdrop.classList.remove('bonus-range-editor-overlay');
    window.AdminBenefitsModal?.hide();
  }

  function openBonusLevelTariffEditor() {
    if (!isBonusLevelEditorActive()) return;
    const current = getActiveBonusLevelForInfo();
    if (!current) return;

    window.AdminBenefitsModal?.show({
      title: '\u041f\u043b\u0430\u0442\u043d\u044b\u0439 \u0442\u0430\u0440\u0438\u0444',
      showBack: false,
      showModeToggle: false,
      onClose: closeBonusLevelTariffEditor,
    });

    const { backdrop, body } = getClientBenefitsOverlayElements();
    if (!body) return;
    if (backdrop) backdrop.classList.add('bonus-range-editor-overlay');
    body.innerHTML = '';

    const frame = window.AdminBenefitsModal?.createScrollableFrame({ hasFooter: true });
    if (!frame?.root || !frame.scrollEl || !frame.footerEl) return;
    body.appendChild(frame.root);

    const shell = document.createElement('div');
    shell.className = 'bonus-range-editor-modal';
    frame.scrollEl.appendChild(shell);

    const header = document.createElement('div');
    header.className = 'bonus-level-tariff-editor-header';
    header.innerHTML = `
      <div class="bonus-range-editor-title">\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0442\u0430\u0440\u0438\u0444\u0430</div>
      <label class="switch bonus-level-tariff-bonus-switch">
        <input class="switch-input" type="checkbox" id="bonusLevelTariffPayWithBonusInput" ${current.tariffPayWithBonus === true ? 'checked' : ''} />
        <span class="switch-ui" aria-hidden="true"></span>
        <span class="switch-text">\u041c\u043e\u0436\u043d\u043e \u043e\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u0430\u043c\u0438</span>
      </label>
    `;
    shell.appendChild(header);

    const rowsRoot = document.createElement('div');
    rowsRoot.className = 'bonus-level-tariff-editor-rows';
    shell.appendChild(rowsRoot);

    const tariffRows = sanitizeBonusTariffRows(current.tariffRows, {
      price: current.tariffPrice,
      discountPercent: current.tariffDiscountPercent,
      periodValue: current.tariffPeriodValue,
      periodUnit: current.tariffPeriodUnit,
    });

    const getTariffUnitLabel = (value) => {
      const normalized = normalizeBonusLevelTariffPeriodUnit(value);
      if (normalized === 'days') return '\u0414\u043d\u0438';
      if (normalized === 'months') return '\u041c\u0435\u0441\u044f\u0446\u044b';
      return '\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e';
    };

    const closeTariffRowUnitMenus = (rowEl, exceptMenu = null) => {
      rowEl.querySelectorAll('[data-tariff-unit-menu]').forEach((menu) => {
        if (menu === exceptMenu) return;
        menu.classList.add('hidden');
      });
      rowEl.querySelectorAll('[data-tariff-unit-wrap]').forEach((wrap) => wrap.classList.remove('is-open'));
      rowEl.querySelectorAll('[data-tariff-unit-trigger], [data-tariff-unit-dots]').forEach((trigger) => {
        trigger.setAttribute('aria-expanded', 'false');
      });
    };

    const syncTariffRowUnit = (rowEl) => {
      const selectedUnit = normalizeBonusLevelTariffPeriodUnit(rowEl.dataset.tariffPeriodUnit);
      const isValueMode = selectedUnit !== 'forever';
      const periodInput = rowEl.querySelector('[data-tariff-row-field="periodValue"]');
      const periodValueWrap = rowEl.querySelector('[data-tariff-period-value-wrap]');
      const periodUnitWrap = rowEl.querySelector('[data-tariff-unit-wrap]');
      const periodUnitText = rowEl.querySelector('[data-tariff-unit-text]');
      if (periodValueWrap) periodValueWrap.classList.toggle('hidden', !isValueMode);
      if (periodUnitWrap) periodUnitWrap.classList.toggle('hidden', isValueMode);
      if (periodInput) periodInput.disabled = !isValueMode;
      if (periodUnitText) periodUnitText.textContent = getTariffUnitLabel(selectedUnit);
      rowEl.querySelectorAll('[data-tariff-period-unit]').forEach((button) => {
        const isActive = String(button.getAttribute('data-tariff-period-unit') || '') === selectedUnit;
        button.classList.toggle('is-active', isActive);
        button.classList.toggle('is-selected', isActive);
        button.setAttribute('aria-selected', isActive ? 'true' : 'false');
      });
    };

    const appendTariffRow = (row = {}) => {
      const rowEl = document.createElement('div');
      rowEl.className = 'bonus-level-tariff-editor-grid bonus-level-tariff-editor-row';
      rowEl.dataset.tariffPeriodUnit = normalizeBonusLevelTariffPeriodUnit(row.periodUnit);
      rowEl.innerHTML = `
        <label class="field-wrap">
          <span class="field-label">\u0426\u0435\u043d\u0430, \u20bd</span>
          <input class="control bonus-level-rule-input" type="number" min="0" step="1" placeholder="0" autocomplete="off" data-tariff-row-field="price" value="${escapeHtml(String(normalizeNumberInputValue(row.price, 0) || 0))}" />
        </label>
        <div class="field-wrap bonus-level-tariff-period-field">
          <span class="field-label">\u041f\u0435\u0440\u0438\u043e\u0434</span>
          <div class="bonus-level-inline-input-wrap bonus-level-tariff-period-value-wrap" data-tariff-period-value-wrap>
            <input class="control bonus-level-rule-input" type="number" min="1" step="1" placeholder="1" autocomplete="off" data-tariff-row-field="periodValue" value="${escapeHtml(String(normalizeBonusLevelTimingValue(row.periodValue, 1) || 1))}" />
            <button type="button" class="bonus-level-inline-menu-btn" data-tariff-unit-dots aria-label="\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0435\u0434\u0438\u043d\u0438\u0446\u0443 \u043f\u0435\u0440\u0438\u043e\u0434\u0430" title="\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0435\u0434\u0438\u043d\u0438\u0446\u0443 \u043f\u0435\u0440\u0438\u043e\u0434\u0430">
              <i class="fas fa-ellipsis-h" aria-hidden="true"></i>
            </button>
            <div class="new-order-right-select-menu no-scrollbar hidden bonus-level-inline-menu" data-tariff-unit-menu role="listbox" aria-label="\u0415\u0434\u0438\u043d\u0438\u0446\u0430">
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="days">\u0414\u043d\u0438</button>
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="months">\u041c\u0435\u0441\u044f\u0446\u044b</button>
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="forever">\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</button>
            </div>
          </div>
          <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-tariff-period-select" data-tariff-unit-wrap>
            <button class="new-order-right-select-trigger bonus-level-unit-select-trigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0415\u0434\u0438\u043d\u0438\u0446\u0430" data-tariff-unit-trigger>
              <span class="cash-toolbar-filter-main"><span data-tariff-unit-text>\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</span></span>
              <i class="fas fa-chevron-down"></i>
            </button>
            <div class="new-order-right-select-menu no-scrollbar hidden" data-tariff-unit-menu role="listbox" aria-label="\u0415\u0434\u0438\u043d\u0438\u0446\u0430">
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="days">\u0414\u043d\u0438</button>
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="months">\u041c\u0435\u0441\u044f\u0446\u044b</button>
              <button class="new-order-right-select-option" type="button" data-tariff-period-unit="forever">\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</button>
            </div>
          </div>
        </div>
        <label class="field-wrap">
          <span class="field-label">\u0421\u043a\u0438\u0434\u043a\u0430 \u043d\u0430 \u0442\u0430\u0440\u0438\u0444, %</span>
          <input class="control bonus-level-rule-input" type="number" min="0" step="0.1" placeholder="0" autocomplete="off" data-tariff-row-field="discountPercent" value="${escapeHtml(String(normalizeBonusPercentInputValue(row.discountPercent, 0) || 0))}" />
        </label>
      `;
      rowsRoot.appendChild(rowEl);
      syncTariffRowUnit(rowEl);
      return rowEl;
    };

    tariffRows.forEach((row) => appendTariffRow(row));

    rowsRoot.addEventListener('click', (event) => {
      const rowEl = event.target.closest('.bonus-level-tariff-editor-row');
      if (!rowEl) return;
      const trigger = event.target.closest('[data-tariff-unit-trigger]');
      const dotsBtn = event.target.closest('[data-tariff-unit-dots]');
      const unitBtn = event.target.closest('[data-tariff-period-unit]');
      if (trigger) {
        event.preventDefault();
        event.stopPropagation();
        const menu = rowEl.querySelector('[data-tariff-unit-wrap] [data-tariff-unit-menu]');
        if (!menu) return;
        const shouldOpen = menu.classList.contains('hidden');
        closeTariffRowUnitMenus(rowEl);
        if (!shouldOpen) return;
        rowEl.querySelector('[data-tariff-unit-wrap]')?.classList.add('is-open');
        menu.classList.remove('hidden');
        trigger.setAttribute('aria-expanded', 'true');
        return;
      }
      if (dotsBtn) {
        event.preventDefault();
        event.stopPropagation();
        const menu = dotsBtn.closest('[data-tariff-period-value-wrap]')?.querySelector('[data-tariff-unit-menu]');
        if (!menu) return;
        const shouldOpen = menu.classList.contains('hidden');
        closeTariffRowUnitMenus(rowEl);
        if (!shouldOpen) return;
        menu.classList.remove('hidden');
        dotsBtn.setAttribute('aria-expanded', 'true');
        return;
      }
      if (unitBtn) {
        event.preventDefault();
        event.stopPropagation();
        rowEl.dataset.tariffPeriodUnit = normalizeBonusLevelTariffPeriodUnit(unitBtn.getAttribute('data-tariff-period-unit'));
        syncTariffRowUnit(rowEl);
        closeTariffRowUnitMenus(rowEl);
      }
    });

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'bonus-level-tariff-add-btn';
    addBtn.textContent = '+';
    addBtn.setAttribute('aria-label', '\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u043f\u043e\u0440\u043e\u0433 \u0442\u0430\u0440\u0438\u0444\u0430');
    addBtn.addEventListener('click', () => {
      appendTariffRow({ price: 0, discountPercent: 0, periodValue: 1, periodUnit: 'months' });
    });
    shell.appendChild(addBtn);

    const actions = document.createElement('div');
    actions.className = 'bonus-range-editor-footer-actions';
    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'shop-checkout-benefits-promo-entry-btn';
    cancelBtn.textContent = '\u041e\u0442\u043c\u0435\u043d\u0430';
    cancelBtn.addEventListener('click', closeBonusLevelTariffEditor);
    actions.appendChild(cancelBtn);

    const saveBtn = document.createElement('button');
    saveBtn.type = 'button';
    saveBtn.className = 'shop-checkout-benefits-promo-entry-btn is-active';
    saveBtn.textContent = '\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c';
    saveBtn.addEventListener('click', () => {
      const nextRows = sanitizeBonusTariffRows(
        Array.from(rowsRoot.querySelectorAll('.bonus-level-tariff-editor-row')).map((rowEl) => ({
          price: rowEl.querySelector('[data-tariff-row-field="price"]')?.value,
          discountPercent: rowEl.querySelector('[data-tariff-row-field="discountPercent"]')?.value,
          periodValue: rowEl.querySelector('[data-tariff-row-field="periodValue"]')?.value,
          periodUnit: rowEl.dataset.tariffPeriodUnit,
        }))
      );
      const firstRow = nextRows[0] || { price: 0, discountPercent: 0, periodValue: 1, periodUnit: 'months' };
      const nextPatch = {
        tariffPrice: normalizeNumberInputValue(firstRow.price, 0),
        tariffDiscountPercent: normalizeBonusPercentInputValue(firstRow.discountPercent, 0),
        tariffPeriodValue: firstRow.periodUnit === 'forever' ? 0 : normalizeBonusLevelTimingValue(firstRow.periodValue, 1),
        tariffPeriodUnit: normalizeBonusLevelTariffPeriodUnit(firstRow.periodUnit),
        tariffRows: nextRows,
        tariffPayWithBonus: header.querySelector('#bonusLevelTariffPayWithBonusInput')?.checked === true,
      };
      applyBonusLevelEditorDraftPatch(nextPatch);
      updateBonusLevelInCollections(current.id, (level) => ({
        ...level,
        ...nextPatch,
      }));
      if (state.bonusCardsEditing !== true) persistBonusCardsStorageSoon();
      renderBonusLevels();
      renderBonusLevelInfo();
      closeBonusLevelTariffEditor();
    });
    actions.appendChild(saveBtn);
    frame.footerEl.appendChild(actions);
  }

  function openBonusLevelRequirementsEditor() {
    if (!isBonusLevelEditorActive()) return;
    const current = getActiveBonusLevelForInfo();
    if (!current) return;

    window.AdminBenefitsModal?.show({
      title: '\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c',
      showBack: false,
      showModeToggle: false,
      onClose: closeBonusLevelRequirementsEditor,
    });

    const { backdrop, body } = getClientBenefitsOverlayElements();
    if (!body) return;
    if (backdrop) backdrop.classList.add('bonus-range-editor-overlay');
    body.innerHTML = '';

    const frame = window.AdminBenefitsModal?.createScrollableFrame({ hasFooter: true });
    if (!frame?.root || !frame.scrollEl || !frame.footerEl) return;
    body.appendChild(frame.root);

    const shell = document.createElement('div');
    shell.className = 'bonus-range-editor-modal';
    frame.scrollEl.appendChild(shell);

    const transitionTitle = document.createElement('div');
    transitionTitle.className = 'bonus-level-modal-section-title';
    transitionTitle.innerHTML = `
      <span>\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c</span>
      <button
        class="bonus-level-range-action-btn"
        type="button"
        id="bonusLevelRequirementsModalInfoBtn"
        aria-label="\u041a\u0430\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u0435\u043d\u044c"
        title="\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u043e"
        aria-expanded="false"
      >
        <i class="fas fa-info"></i>
      </button>
    `;
    shell.appendChild(transitionTitle);
    const transitionInfoBtn = transitionTitle.querySelector('#bonusLevelRequirementsModalInfoBtn');
    if (transitionInfoBtn) {
      transitionInfoBtn.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        openBonusLevelHelpPopover(transitionInfoBtn, formatBonusLevelRequirementsHelpText());
      });
    }

    const note = document.createElement('div');
    note.className = 'bonus-range-editor-row';
    note.textContent = '\u041f\u0443\u0441\u0442\u044b\u0435 \u043f\u043e\u043b\u044f \u043d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f. \u041f\u0443\u0441\u0442\u043e\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 - \u0431\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e.';
    shell.appendChild(note);

    const referralRequirementsEnabled = isReferralSystemEnabled();
    const initialPeriodDays = normalizeBonusLevelRequirementValue(current.requirementPeriodDays);
    let selectedMode = 'or';
    let selectedReferralMode = 'or';
    let selectedRetentionStrategy = normalizeBonusLevelRetentionStrategy(current.retentionStrategy);
    let selectedRetentionMode = 'or';
    let selectedRetentionReferralMode = 'or';
    let selectedPeriodUnit = initialPeriodDays == null ? 'forever' : 'days';
    const initialRetentionAmount = normalizeBonusLevelRequirementValue(current.retentionAmount);
    const initialRetentionOrders = normalizeBonusLevelRequirementValue(current.retentionOrders);
    const initialRetentionReferrals = normalizeBonusLevelRequirementValue(current.retentionReferrals);
    const initialRetentionBonusAccrued = normalizeBonusLevelRequirementValue(current.retentionBonusAccrued);
    const initialRetentionBonusRedeemed = normalizeBonusLevelRequirementValue(current.retentionBonusRedeemed);

    const periodControls = document.createElement('div');
    periodControls.className = 'bonus-level-requirements-top-grid bonus-level-requirements-top-grid--match';
    periodControls.innerHTML = `
      <div class="field-wrap bonus-level-requirement-period-field">
        <span class="field-label" for="bonusLevelRequirementModalPeriodInput">\u041f\u0435\u0440\u0438\u043e\u0434</span>
        <div class="bonus-level-inline-input-wrap bonus-level-requirement-period-value-wrap" id="bonusLevelRequirementPeriodValueWrap">
          <input id="bonusLevelRequirementModalPeriodInput" class="control bonus-level-rule-input" type="number" min="0" step="1" placeholder="0" autocomplete="off" value="${escapeHtml(String(initialPeriodDays ?? ''))}" />
          <button type="button" class="bonus-level-inline-menu-btn" id="bonusLevelRequirementPeriodDotsBtn" aria-label="\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0435\u0434\u0438\u043d\u0438\u0446\u0443 \u043f\u0435\u0440\u0438\u043e\u0434\u0430" title="\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0435\u0434\u0438\u043d\u0438\u0446\u0443 \u043f\u0435\u0440\u0438\u043e\u0434\u0430">
            <i class="fas fa-ellipsis-h" aria-hidden="true"></i>
          </button>
          <div class="new-order-right-select-menu no-scrollbar hidden bonus-level-inline-menu" id="bonusLevelRequirementPeriodInlineMenu" role="listbox" aria-label="\u041f\u0435\u0440\u0438\u043e\u0434">
            <button class="new-order-right-select-option" type="button" data-period-unit="days">\u0414\u043d\u0438</button>
            <button class="new-order-right-select-option" type="button" data-period-unit="forever">\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</button>
          </div>
        </div>
        <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-requirement-period-select" id="bonusLevelRequirementPeriodUnitWrap">
          <button class="new-order-right-select-trigger bonus-level-unit-select-trigger" id="bonusLevelRequirementPeriodUnitTrigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u041f\u0435\u0440\u0438\u043e\u0434">
            <span class="cash-toolbar-filter-main"><span id="bonusLevelRequirementPeriodUnitText">\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</span></span>
            <i class="fas fa-chevron-down"></i>
          </button>
          <div class="new-order-right-select-menu no-scrollbar hidden" id="bonusLevelRequirementPeriodUnitMenu" role="listbox" aria-label="\u041f\u0435\u0440\u0438\u043e\u0434">
            <button class="new-order-right-select-option" type="button" data-period-unit="days">\u0414\u043d\u0438</button>
            <button class="new-order-right-select-option" type="button" data-period-unit="forever">\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e</button>
          </div>
        </div>
      </div>
    `;
    const matchControl = document.createElement('label');
    matchControl.className = 'field-wrap bonus-level-match-count-field';
    matchControl.innerHTML = `
      <span class="field-label" for="bonusLevelRequirementMatchCountTrigger">\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432</span>
      <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-match-count-select" id="bonusLevelRequirementMatchCountWrap">
        <button class="new-order-right-select-trigger bonus-level-unit-select-trigger" id="bonusLevelRequirementMatchCountTrigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432">
          <span class="cash-toolbar-filter-main"><span id="bonusLevelRequirementMatchCountText">${escapeHtml(String(Math.max(1, normalizeNumberInputValue(current.requirementMatchCount, 1))))}</span></span>
          <i class="fas fa-chevron-down"></i>
        </button>
        <div class="new-order-right-select-menu no-scrollbar hidden" id="bonusLevelRequirementMatchCountMenu" role="listbox" aria-label="\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432"></div>
      </div>
    `;
    periodControls.appendChild(matchControl);
    shell.appendChild(periodControls);

    const fields = document.createElement('div');
    fields.className = 'bonus-level-condition-editor';
    shell.appendChild(fields);

    const conditionRowsRoot = document.createElement('div');
    conditionRowsRoot.className = 'bonus-level-condition-rows';
    fields.appendChild(conditionRowsRoot);
    const requirementMatchCountWrap = matchControl.querySelector('#bonusLevelRequirementMatchCountWrap');
    const requirementMatchCountTrigger = matchControl.querySelector('#bonusLevelRequirementMatchCountTrigger');
    const requirementMatchCountMenu = matchControl.querySelector('#bonusLevelRequirementMatchCountMenu');
    const requirementMatchCountText = matchControl.querySelector('#bonusLevelRequirementMatchCountText');
    let selectedRequirementMatchCount = Math.max(1, normalizeNumberInputValue(current.requirementMatchCount, 1));

    const conditionTypes = [
      { key: 'amount', label: '\u0421\u0443\u043c\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u043e\u0432', value: normalizeBonusLevelRequirementValue(current.requirementAmount) },
      { key: 'orders', label: '\u041a\u043e\u043b-\u0432\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432', value: normalizeBonusLevelRequirementValue(current.requirementOrders) },
      { key: 'referrals', label: '\u041f\u0440\u0438\u0433\u043b. \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u044b', value: normalizeBonusLevelRequirementValue(current.requirementReferrals) },
      { key: 'bonusAccrued', label: '\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432', value: normalizeBonusLevelRequirementValue(current.requirementBonusAccrued) },
      { key: 'bonusRedeemed', label: '\u041f\u043e\u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0431\u043e\u043d\u0443\u0441\u043e\u0432', value: normalizeBonusLevelRequirementValue(current.requirementBonusRedeemed) },
    ].filter((item) => item.key !== 'referrals' || referralRequirementsEnabled);

    const getConditionTypeLabel = (type) => (
      conditionTypes.find((item) => item.key === type)?.label || conditionTypes[0]?.label || ''
    );
    const closeConditionMenus = (exceptMenu = null) => {
      shell.querySelectorAll('.bonus-level-condition-type-menu').forEach((menu) => {
        if (menu === exceptMenu) return;
        menu.classList.add('hidden');
      });
      shell.querySelectorAll('.bonus-level-condition-type-wrap').forEach((wrap) => {
        const menu = wrap.querySelector('.bonus-level-condition-type-menu');
        if (menu === exceptMenu) return;
        wrap.classList.remove('is-open');
        wrap.querySelector('.bonus-level-condition-type-trigger')?.setAttribute('aria-expanded', 'false');
      });
    };
    if (bonusLevelRequirementsOutsideClickHandler) {
      document.removeEventListener('click', bonusLevelRequirementsOutsideClickHandler);
    }
    bonusLevelRequirementsOutsideClickHandler = (event) => {
      if (event.target.closest('.bonus-level-condition-type-wrap')) return;
      closeConditionMenus();
    };
    document.addEventListener('click', bonusLevelRequirementsOutsideClickHandler);
    let addConditionBtn = null;
    const getUsedConditionTypes = (exceptRow = null) => new Set(
      Array.from(conditionRowsRoot.querySelectorAll('.bonus-level-condition-row'))
        .filter((row) => row !== exceptRow)
        .map((row) => String(row.dataset.conditionType || ''))
        .filter(Boolean)
    );
    const syncConditionAvailability = () => {
      const usedCount = getUsedConditionTypes().size || 1;
      selectedRequirementMatchCount = Math.min(Math.max(1, selectedRequirementMatchCount), usedCount);
      if (requirementMatchCountText) requirementMatchCountText.textContent = String(selectedRequirementMatchCount);
      if (requirementMatchCountMenu) {
        requirementMatchCountMenu.innerHTML = Array.from({ length: usedCount }, (_, idx) => {
          const value = idx + 1;
          return `<button class="new-order-right-select-option${value === selectedRequirementMatchCount ? ' is-selected' : ''}" type="button" data-match-count="${value}">${value}</button>`;
        }).join('');
      }
      conditionRowsRoot.querySelectorAll('.bonus-level-condition-row').forEach((row) => {
        const usedTypes = getUsedConditionTypes(row);
        row.querySelectorAll('[data-condition-type-option]').forEach((button) => {
          const type = String(button.dataset.conditionTypeOption || '');
          const isDisabled = usedTypes.has(type);
          button.classList.toggle('hidden', isDisabled);
          button.disabled = isDisabled;
          button.classList.toggle('is-disabled', isDisabled);
          button.setAttribute('aria-disabled', isDisabled ? 'true' : 'false');
        });
      });
      if (!addConditionBtn) return;
      const hasFreeType = conditionTypes.some((item) => !getUsedConditionTypes().has(item.key));
      addConditionBtn.disabled = !hasFreeType;
      addConditionBtn.classList.toggle('is-disabled', !hasFreeType);
    };
    const syncConditionTypeRow = (rowEl, type) => {
      if (!(rowEl instanceof Element)) return;
      const normalizedType = conditionTypes.some((item) => item.key === type) ? type : conditionTypes[0]?.key;
      rowEl.dataset.conditionType = normalizedType || '';
      const textEl = rowEl.querySelector('.bonus-level-condition-type-text');
      if (textEl) textEl.textContent = getConditionTypeLabel(normalizedType);
      rowEl.querySelectorAll('[data-condition-type-option]').forEach((button) => {
        const isSelected = String(button.dataset.conditionTypeOption || '') === normalizedType;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-selected', isSelected ? 'true' : 'false');
      });
    };
    const appendRequirementConditionRow = (type = '', value = '') => {
      const normalizedType = conditionTypes.some((item) => item.key === type) ? type : conditionTypes[0]?.key;
      if (!normalizedType) return null;
      const rowEl = document.createElement('div');
      rowEl.className = 'bonus-level-condition-row';
      rowEl.dataset.conditionType = normalizedType;
      rowEl.innerHTML = `
        <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-condition-type-wrap">
          <button class="new-order-right-select-trigger bonus-level-unit-select-trigger bonus-level-condition-type-trigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u0435">
            <span class="cash-toolbar-filter-main"><span class="bonus-level-condition-type-text">${escapeHtml(getConditionTypeLabel(normalizedType))}</span></span>
            <i class="fas fa-chevron-down"></i>
          </button>
          <div class="new-order-right-select-menu no-scrollbar hidden bonus-level-condition-type-menu" role="listbox" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u0435">
            ${conditionTypes.map((item) => `
              <button class="new-order-right-select-option" type="button" data-condition-type-option="${escapeHtml(item.key)}">${escapeHtml(item.label)}</button>
            `).join('')}
          </div>
        </div>
        <input class="control bonus-level-rule-input bonus-level-condition-value-input" type="number" min="0" step="1" placeholder="\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435" autocomplete="off" value="${escapeHtml(String(value ?? ''))}" />
        <button type="button" class="bonus-range-editor-delete-btn" aria-label="\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435" title="\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435">
          <i class="fas fa-times" aria-hidden="true"></i>
        </button>
      `;
      const trigger = rowEl.querySelector('.bonus-level-condition-type-trigger');
      const wrap = rowEl.querySelector('.bonus-level-condition-type-wrap');
      const menu = rowEl.querySelector('.bonus-level-condition-type-menu');
      trigger?.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const shouldOpen = menu?.classList.contains('hidden');
        closeConditionMenus();
        if (!shouldOpen || !menu) return;
        syncConditionAvailability();
        wrap?.classList.add('is-open');
        menu.classList.remove('hidden');
        trigger.setAttribute('aria-expanded', 'true');
      });
      rowEl.querySelectorAll('[data-condition-type-option]').forEach((button) => {
        button.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
          if (button.disabled) return;
          syncConditionTypeRow(rowEl, String(button.dataset.conditionTypeOption || ''));
          syncConditionAvailability();
          syncMatchedRetentionValues();
          closeConditionMenus();
        });
      });
      rowEl.querySelector('.bonus-range-editor-delete-btn')?.addEventListener('click', () => {
        rowEl.remove();
        syncConditionAvailability();
        syncMatchedRetentionValues();
      });
      rowEl.querySelector('.bonus-level-condition-value-input')?.addEventListener('input', () => {
        syncMatchedRetentionValues();
      });
      conditionRowsRoot.appendChild(rowEl);
      syncConditionTypeRow(rowEl, normalizedType);
      syncConditionAvailability();
      return rowEl;
    };
    conditionTypes
      .filter((item) => item.value != null)
      .forEach((item) => appendRequirementConditionRow(item.key, item.value));
    if (!conditionRowsRoot.children.length) appendRequirementConditionRow(conditionTypes[0]?.key || 'amount', '');

    addConditionBtn = document.createElement('button');
    addConditionBtn.type = 'button';
    addConditionBtn.className = 'bonus-range-editor-add-btn';
    addConditionBtn.textContent = '+';
    addConditionBtn.setAttribute('aria-label', '\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435');
    addConditionBtn.addEventListener('click', () => {
      const usedTypes = new Set(Array.from(conditionRowsRoot.querySelectorAll('.bonus-level-condition-row')).map((row) => row.dataset.conditionType));
      const nextType = conditionTypes.find((item) => !usedTypes.has(item.key))?.key;
      if (!nextType) return;
      appendRequirementConditionRow(nextType, '');
    });
    fields.appendChild(addConditionBtn);
    syncConditionAvailability();

    const retentionSection = document.createElement('div');
    retentionSection.className = 'bonus-level-retention-section hidden';
    retentionSection.innerHTML = `
      <div class="bonus-level-modal-section-title">
        <span>\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u0443\u0440\u043e\u0432\u043d\u044f</span>
      </div>
      <div class="bonus-level-requirements-top-grid bonus-level-requirements-top-grid--match">
        <div class="field-wrap bonus-level-retention-strategy-field">
          <span class="field-label" for="bonusLevelRetentionStrategyTrigger">\u0423\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435</span>
          <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-retention-strategy-select" id="bonusLevelRetentionStrategyWrap">
            <button class="new-order-right-select-trigger bonus-level-unit-select-trigger" id="bonusLevelRetentionStrategyTrigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f">
              <span class="cash-toolbar-filter-main"><span id="bonusLevelRetentionStrategyText">\u0421\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442</span></span>
              <i class="fas fa-chevron-down"></i>
            </button>
            <div class="new-order-right-select-menu no-scrollbar hidden" id="bonusLevelRetentionStrategyMenu" role="listbox" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f">
              <button class="new-order-right-select-option" type="button" data-retention-strategy="match">\u0421\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442</button>
              <button class="new-order-right-select-option" type="button" data-retention-strategy="custom">\u0421\u0432\u043e\u0438</button>
            </div>
          </div>
        </div>
        <label class="field-wrap bonus-level-match-count-field">
          <span class="field-label" for="bonusLevelRetentionMatchCountTrigger">\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432</span>
          <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-match-count-select" id="bonusLevelRetentionMatchCountWrap">
            <button class="new-order-right-select-trigger bonus-level-unit-select-trigger" id="bonusLevelRetentionMatchCountTrigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432">
              <span class="cash-toolbar-filter-main"><span id="bonusLevelRetentionMatchCountText">${escapeHtml(String(Math.max(1, normalizeNumberInputValue(current.retentionMatchCount, 1))))}</span></span>
              <i class="fas fa-chevron-down"></i>
            </button>
            <div class="new-order-right-select-menu no-scrollbar hidden" id="bonusLevelRetentionMatchCountMenu" role="listbox" aria-label="\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u0443\u043d\u043a\u0442\u043e\u0432"></div>
          </div>
        </label>
      </div>
      <div class="bonus-level-condition-editor bonus-level-retention-condition-editor">
        <div class="bonus-level-condition-rows" id="bonusLevelRetentionConditionRows"></div>
        <button type="button" class="bonus-range-editor-add-btn" id="bonusLevelRetentionAddConditionBtn" aria-label="\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435">+</button>
      </div>
      <div class="hidden">
        <input id="bonusLevelRetentionModalAmountInput" value="${escapeHtml(String(normalizeBonusLevelRequirementValue(current.retentionAmount) ?? ''))}" />
        <input id="bonusLevelRetentionModalOrdersInput" value="${escapeHtml(String(normalizeBonusLevelRequirementValue(current.retentionOrders) ?? ''))}" />
        <input id="bonusLevelRetentionModalReferralsInput" value="${escapeHtml(String(normalizeBonusLevelRequirementValue(current.retentionReferrals) ?? ''))}" />
        <input id="bonusLevelRetentionModalBonusAccruedInput" value="${escapeHtml(String(normalizeBonusLevelRequirementValue(current.retentionBonusAccrued) ?? ''))}" />
        <input id="bonusLevelRetentionModalBonusRedeemedInput" value="${escapeHtml(String(normalizeBonusLevelRequirementValue(current.retentionBonusRedeemed) ?? ''))}" />
      </div>
    `;
    shell.appendChild(retentionSection);

    const modeToggleBtn = fields.querySelector('#bonusLevelRequirementModeToggle');
    const syncModeButton = () => {
      if (!modeToggleBtn) return;
      const normalizedMode = normalizeBonusLevelRequirementMode(selectedMode);
      modeToggleBtn.textContent = normalizedMode === 'or' ? '\u0438\u043b\u0438' : '\u0438';
      modeToggleBtn.classList.add('is-active');
      modeToggleBtn.setAttribute('aria-pressed', normalizedMode === 'or' ? 'true' : 'false');
    };
    if (modeToggleBtn) {
      modeToggleBtn.addEventListener('click', () => {
        selectedMode = normalizeBonusLevelRequirementMode(selectedMode) === 'or' ? 'and' : 'or';
        syncModeButton();
        syncMatchedRetentionValues();
      });
    }
    syncModeButton();

    const referralModeToggleBtn = fields.querySelector('#bonusLevelRequirementReferralModeToggle');
    const syncReferralModeButton = () => {
      if (!referralModeToggleBtn) return;
      const normalizedMode = normalizeBonusLevelRequirementMode(selectedReferralMode);
      referralModeToggleBtn.textContent = normalizedMode === 'or' ? '\u0438\u043b\u0438' : '\u0438';
      referralModeToggleBtn.classList.add('is-active');
      referralModeToggleBtn.setAttribute('aria-pressed', normalizedMode === 'or' ? 'true' : 'false');
    };
    if (referralModeToggleBtn) {
      referralModeToggleBtn.addEventListener('click', () => {
        selectedReferralMode = normalizeBonusLevelRequirementMode(selectedReferralMode) === 'or' ? 'and' : 'or';
        syncReferralModeButton();
        syncMatchedRetentionValues();
      });
    }
    syncReferralModeButton();

    const retentionModeToggleBtn = retentionSection.querySelector('#bonusLevelRetentionModeToggle');
    const syncRetentionModeButton = () => {
      if (!retentionModeToggleBtn) return;
      const normalizedMode = normalizeBonusLevelRequirementMode(selectedRetentionMode);
      retentionModeToggleBtn.textContent = normalizedMode === 'or' ? '\u0438\u043b\u0438' : '\u0438';
      retentionModeToggleBtn.classList.add('is-active');
      retentionModeToggleBtn.setAttribute('aria-pressed', normalizedMode === 'or' ? 'true' : 'false');
    };
    if (retentionModeToggleBtn) {
      retentionModeToggleBtn.addEventListener('click', () => {
        if (selectedRetentionStrategy !== 'custom') return;
        selectedRetentionMode = normalizeBonusLevelRequirementMode(selectedRetentionMode) === 'or' ? 'and' : 'or';
        syncRetentionModeButton();
      });
    }
    syncRetentionModeButton();

    const retentionReferralModeToggleBtn = retentionSection.querySelector('#bonusLevelRetentionReferralModeToggle');
    const syncRetentionReferralModeButton = () => {
      if (!retentionReferralModeToggleBtn) return;
      const normalizedMode = normalizeBonusLevelRequirementMode(selectedRetentionReferralMode);
      retentionReferralModeToggleBtn.textContent = normalizedMode === 'or' ? '\u0438\u043b\u0438' : '\u0438';
      retentionReferralModeToggleBtn.classList.add('is-active');
      retentionReferralModeToggleBtn.setAttribute('aria-pressed', normalizedMode === 'or' ? 'true' : 'false');
    };
    if (retentionReferralModeToggleBtn) {
      retentionReferralModeToggleBtn.addEventListener('click', () => {
        if (selectedRetentionStrategy !== 'custom') return;
        selectedRetentionReferralMode = normalizeBonusLevelRequirementMode(selectedRetentionReferralMode) === 'or' ? 'and' : 'or';
        syncRetentionReferralModeButton();
      });
    }
    syncRetentionReferralModeButton();

    const collectRequirementConditionValues = () => {
      const values = { amountRaw: '', ordersRaw: '', referralsRaw: '', bonusAccruedRaw: '', bonusRedeemedRaw: '' };
      conditionRowsRoot.querySelectorAll('.bonus-level-condition-row').forEach((row) => {
        const type = String(row.dataset.conditionType || '');
        const raw = String(row.querySelector('.bonus-level-condition-value-input')?.value ?? '').trim();
        if (type === 'amount') values.amountRaw = raw;
        if (type === 'orders') values.ordersRaw = raw;
        if (type === 'referrals') values.referralsRaw = raw;
        if (type === 'bonusAccrued') values.bonusAccruedRaw = raw;
        if (type === 'bonusRedeemed') values.bonusRedeemedRaw = raw;
      });
      return values;
    };
    const retentionAmountInput = retentionSection.querySelector('#bonusLevelRetentionModalAmountInput');
    const retentionOrdersInput = retentionSection.querySelector('#bonusLevelRetentionModalOrdersInput');
    const retentionReferralsInput = retentionSection.querySelector('#bonusLevelRetentionModalReferralsInput');
    const retentionBonusAccruedInput = retentionSection.querySelector('#bonusLevelRetentionModalBonusAccruedInput');
    const retentionBonusRedeemedInput = retentionSection.querySelector('#bonusLevelRetentionModalBonusRedeemedInput');
    const retentionMatchCountWrap = retentionSection.querySelector('#bonusLevelRetentionMatchCountWrap');
    const retentionMatchCountTrigger = retentionSection.querySelector('#bonusLevelRetentionMatchCountTrigger');
    const retentionMatchCountMenu = retentionSection.querySelector('#bonusLevelRetentionMatchCountMenu');
    const retentionMatchCountText = retentionSection.querySelector('#bonusLevelRetentionMatchCountText');
    const retentionRowsRoot = retentionSection.querySelector('#bonusLevelRetentionConditionRows');
    const retentionAddConditionBtn = retentionSection.querySelector('#bonusLevelRetentionAddConditionBtn');
    const retentionStrategyWrap = retentionSection.querySelector('#bonusLevelRetentionStrategyWrap');
    const retentionStrategyTrigger = retentionSection.querySelector('#bonusLevelRetentionStrategyTrigger');
    const retentionStrategyMenu = retentionSection.querySelector('#bonusLevelRetentionStrategyMenu');
    const retentionStrategyText = retentionSection.querySelector('#bonusLevelRetentionStrategyText');
    let selectedRetentionMatchCount = Math.max(1, normalizeNumberInputValue(current.retentionMatchCount, 1));
    const getRetentionStrategyLabel = (strategy) => strategy === 'custom' ? '\u0421\u0432\u043e\u0438' : '\u0421\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442';
    const syncRetentionHiddenInputs = () => {
      const values = { amountRaw: '', ordersRaw: '', referralsRaw: '', bonusAccruedRaw: '', bonusRedeemedRaw: '' };
      retentionRowsRoot?.querySelectorAll('.bonus-level-condition-row').forEach((row) => {
        const type = String(row.dataset.conditionType || '');
        const raw = String(row.querySelector('.bonus-level-condition-value-input')?.value ?? '').trim();
        if (type === 'amount') values.amountRaw = raw;
        if (type === 'orders') values.ordersRaw = raw;
        if (type === 'referrals') values.referralsRaw = raw;
        if (type === 'bonusAccrued') values.bonusAccruedRaw = raw;
        if (type === 'bonusRedeemed') values.bonusRedeemedRaw = raw;
      });
      if (retentionAmountInput) retentionAmountInput.value = values.amountRaw;
      if (retentionOrdersInput) retentionOrdersInput.value = values.ordersRaw;
      if (retentionReferralsInput) retentionReferralsInput.value = values.referralsRaw;
      if (retentionBonusAccruedInput) retentionBonusAccruedInput.value = values.bonusAccruedRaw;
      if (retentionBonusRedeemedInput) retentionBonusRedeemedInput.value = values.bonusRedeemedRaw;
    };
    const getRetentionUsedConditionTypes = (exceptRow = null) => new Set(
      Array.from(retentionRowsRoot?.querySelectorAll('.bonus-level-condition-row') || [])
        .filter((row) => row !== exceptRow)
        .map((row) => String(row.dataset.conditionType || ''))
        .filter(Boolean)
    );
    const syncRetentionConditionAvailability = () => {
      const isCustom = selectedRetentionStrategy === 'custom';
      const usedCount = getRetentionUsedConditionTypes().size || 1;
      selectedRetentionMatchCount = Math.min(Math.max(1, selectedRetentionMatchCount), usedCount);
      if (retentionMatchCountText) retentionMatchCountText.textContent = String(selectedRetentionMatchCount);
      if (retentionMatchCountMenu) {
        retentionMatchCountMenu.innerHTML = Array.from({ length: usedCount }, (_, index) => {
          const value = index + 1;
          return `<button class="new-order-right-select-option${value === selectedRetentionMatchCount ? ' is-selected' : ''}" type="button" data-retention-match-count="${value}">${value}</button>`;
        }).join('');
      }
      if (retentionMatchCountTrigger) retentionMatchCountTrigger.disabled = !isCustom;
      if (retentionMatchCountWrap) retentionMatchCountWrap.classList.toggle('is-disabled', !isCustom);
      retentionRowsRoot?.querySelectorAll('.bonus-level-condition-row').forEach((row) => {
        const usedTypes = getRetentionUsedConditionTypes(row);
        row.querySelectorAll('[data-condition-type-option]').forEach((button) => {
          const type = String(button.dataset.conditionTypeOption || '');
          const isDisabled = !isCustom || usedTypes.has(type);
          button.classList.toggle('hidden', usedTypes.has(type));
          button.disabled = isDisabled;
          button.classList.toggle('is-disabled', isDisabled);
          button.setAttribute('aria-disabled', isDisabled ? 'true' : 'false');
        });
        row.querySelector('.bonus-level-condition-type-trigger')?.toggleAttribute('disabled', !isCustom);
        row.querySelector('.bonus-level-condition-value-input')?.toggleAttribute('disabled', !isCustom);
        row.querySelector('.bonus-range-editor-delete-btn')?.toggleAttribute('disabled', !isCustom);
      });
      if (!retentionAddConditionBtn) return;
      const hasFreeType = conditionTypes.some((item) => !getRetentionUsedConditionTypes().has(item.key));
      retentionAddConditionBtn.disabled = !isCustom || !hasFreeType;
      retentionAddConditionBtn.classList.toggle('is-disabled', !isCustom || !hasFreeType);
    };
    const appendRetentionConditionRow = (type = '', value = '') => {
      if (!(retentionRowsRoot instanceof Element)) return null;
      const normalizedType = conditionTypes.some((item) => item.key === type) ? type : conditionTypes[0]?.key;
      if (!normalizedType) return null;
      const rowEl = document.createElement('div');
      rowEl.className = 'bonus-level-condition-row';
      rowEl.dataset.conditionType = normalizedType;
      rowEl.innerHTML = `
        <div class="new-order-right-select-wrap settings-delivery-city-selector bonus-level-unit-select bonus-level-condition-type-wrap">
          <button class="new-order-right-select-trigger bonus-level-unit-select-trigger bonus-level-condition-type-trigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u0435">
            <span class="cash-toolbar-filter-main"><span class="bonus-level-condition-type-text">${escapeHtml(getConditionTypeLabel(normalizedType))}</span></span>
            <i class="fas fa-chevron-down"></i>
          </button>
          <div class="new-order-right-select-menu no-scrollbar hidden bonus-level-condition-type-menu" role="listbox" aria-label="\u0423\u0441\u043b\u043e\u0432\u0438\u0435">
            ${conditionTypes.map((item) => `
              <button class="new-order-right-select-option" type="button" data-condition-type-option="${escapeHtml(item.key)}">${escapeHtml(item.label)}</button>
            `).join('')}
          </div>
        </div>
        <input class="control bonus-level-rule-input bonus-level-condition-value-input" type="number" min="0" step="1" placeholder="\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435" autocomplete="off" value="${escapeHtml(String(value ?? ''))}" />
        <button type="button" class="bonus-range-editor-delete-btn" aria-label="\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435" title="\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u0435">
          <i class="fas fa-times" aria-hidden="true"></i>
        </button>
      `;
      const trigger = rowEl.querySelector('.bonus-level-condition-type-trigger');
      const wrap = rowEl.querySelector('.bonus-level-condition-type-wrap');
      const menu = rowEl.querySelector('.bonus-level-condition-type-menu');
      trigger?.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (selectedRetentionStrategy !== 'custom') return;
        const shouldOpen = menu?.classList.contains('hidden');
        closeConditionMenus();
        if (!shouldOpen || !menu) return;
        syncRetentionConditionAvailability();
        wrap?.classList.add('is-open');
        menu.classList.remove('hidden');
        trigger.setAttribute('aria-expanded', 'true');
      });
      rowEl.querySelectorAll('[data-condition-type-option]').forEach((button) => {
        button.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
          if (button.disabled) return;
          rowEl.dataset.conditionType = String(button.dataset.conditionTypeOption || '');
          rowEl.querySelector('.bonus-level-condition-type-text').textContent = getConditionTypeLabel(rowEl.dataset.conditionType);
          syncRetentionHiddenInputs();
          syncRetentionConditionAvailability();
          closeConditionMenus();
        });
      });
      rowEl.querySelector('.bonus-range-editor-delete-btn')?.addEventListener('click', () => {
        rowEl.remove();
        syncRetentionHiddenInputs();
        syncRetentionConditionAvailability();
      });
      rowEl.querySelector('.bonus-level-condition-value-input')?.addEventListener('input', () => {
        syncRetentionHiddenInputs();
      });
      retentionRowsRoot.appendChild(rowEl);
      syncRetentionConditionAvailability();
      return rowEl;
    };
    const renderRetentionConditionRows = (values) => {
      if (!(retentionRowsRoot instanceof Element)) return;
      retentionRowsRoot.innerHTML = '';
      const rows = [
        { type: 'amount', value: values.amountRaw },
        { type: 'orders', value: values.ordersRaw },
        { type: 'referrals', value: values.referralsRaw },
        { type: 'bonusAccrued', value: values.bonusAccruedRaw },
        { type: 'bonusRedeemed', value: values.bonusRedeemedRaw },
      ].filter((row) => conditionTypes.some((item) => item.key === row.type) && String(row.value ?? '').trim() !== '');
      (rows.length ? rows : [{ type: conditionTypes[0]?.key || 'amount', value: '' }])
        .forEach((row) => appendRetentionConditionRow(row.type, row.value));
      syncRetentionHiddenInputs();
      syncRetentionConditionAvailability();
    };
    const closeRetentionStrategyMenu = () => {
      if (retentionStrategyMenu) retentionStrategyMenu.classList.add('hidden');
      if (retentionStrategyWrap) retentionStrategyWrap.classList.remove('is-open');
      if (retentionStrategyTrigger) retentionStrategyTrigger.setAttribute('aria-expanded', 'false');
    };
    const syncRetentionStrategyUi = () => {
      const isCustom = selectedRetentionStrategy === 'custom';
      if (retentionStrategyText) retentionStrategyText.textContent = getRetentionStrategyLabel(selectedRetentionStrategy);
      renderRetentionConditionRows(isCustom
        ? {
            amountRaw: String(initialRetentionAmount ?? ''),
            ordersRaw: String(initialRetentionOrders ?? ''),
            referralsRaw: String(initialRetentionReferrals ?? ''),
            bonusAccruedRaw: String(initialRetentionBonusAccrued ?? ''),
            bonusRedeemedRaw: String(initialRetentionBonusRedeemed ?? ''),
          }
        : collectRequirementConditionValues()
      );
      selectedRetentionMatchCount = isCustom
        ? Math.max(1, normalizeNumberInputValue(current.retentionMatchCount, 1))
        : selectedRequirementMatchCount;
      if (!isCustom) {
        selectedRetentionMode = normalizeBonusLevelRequirementMode(selectedMode);
        selectedRetentionReferralMode = normalizeBonusLevelRequirementMode(selectedReferralMode);
        syncRetentionModeButton();
        syncRetentionReferralModeButton();
      }
      syncRetentionConditionAvailability();
      retentionSection.querySelectorAll('[data-retention-strategy]').forEach((button) => {
        const isSelected = String(button.dataset.retentionStrategy || '') === selectedRetentionStrategy;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-selected', isSelected ? 'true' : 'false');
      });
    };
    const selectRetentionStrategy = (strategy) => {
      selectedRetentionStrategy = normalizeBonusLevelRetentionStrategy(strategy);
      syncRetentionStrategyUi();
      closeRetentionStrategyMenu();
    };
    if (retentionStrategyTrigger && retentionStrategyMenu) {
      retentionStrategyTrigger.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const shouldOpen = retentionStrategyMenu.classList.contains('hidden');
        closeRetentionStrategyMenu();
        if (!shouldOpen) return;
        retentionStrategyWrap?.classList.add('is-open');
        retentionStrategyMenu.classList.remove('hidden');
        retentionStrategyTrigger.setAttribute('aria-expanded', 'true');
      });
    }
    retentionSection.querySelectorAll('[data-retention-strategy]').forEach((button) => {
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        selectRetentionStrategy(String(button.dataset.retentionStrategy || 'match'));
      });
    });
    syncRetentionStrategyUi();

    const periodValueWrap = periodControls.querySelector('#bonusLevelRequirementPeriodValueWrap');
    const periodUnitWrap = periodControls.querySelector('#bonusLevelRequirementPeriodUnitWrap');
    const periodUnitTrigger = periodControls.querySelector('#bonusLevelRequirementPeriodUnitTrigger');
    const periodUnitMenu = periodControls.querySelector('#bonusLevelRequirementPeriodUnitMenu');
    const periodInlineMenu = periodControls.querySelector('#bonusLevelRequirementPeriodInlineMenu');
    const periodDotsBtn = periodControls.querySelector('#bonusLevelRequirementPeriodDotsBtn');
    const periodUnitText = periodControls.querySelector('#bonusLevelRequirementPeriodUnitText');

    const getPeriodUnitLabel = (unit) => unit === 'days' ? '\u0414\u043d\u0438' : '\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e';
    const closePeriodMenus = () => {
      closeConditionMenus();
      if (periodUnitMenu) periodUnitMenu.classList.add('hidden');
      if (periodInlineMenu) periodInlineMenu.classList.add('hidden');
      if (requirementMatchCountMenu) requirementMatchCountMenu.classList.add('hidden');
      if (retentionMatchCountMenu) retentionMatchCountMenu.classList.add('hidden');
      closeRetentionStrategyMenu();
      if (periodUnitWrap) periodUnitWrap.classList.remove('is-open');
      if (periodUnitTrigger) periodUnitTrigger.setAttribute('aria-expanded', 'false');
      if (periodDotsBtn) periodDotsBtn.setAttribute('aria-expanded', 'false');
      if (requirementMatchCountWrap) requirementMatchCountWrap.classList.remove('is-open');
      if (requirementMatchCountTrigger) requirementMatchCountTrigger.setAttribute('aria-expanded', 'false');
      if (retentionMatchCountWrap) retentionMatchCountWrap.classList.remove('is-open');
      if (retentionMatchCountTrigger) retentionMatchCountTrigger.setAttribute('aria-expanded', 'false');
    };
    const syncPeriodUi = () => {
      const isDays = selectedPeriodUnit === 'days';
      if (periodValueWrap) periodValueWrap.classList.toggle('hidden', !isDays);
      if (periodUnitWrap) periodUnitWrap.classList.toggle('hidden', isDays);
      retentionSection.classList.toggle('hidden', !isDays);
      if (periodUnitText) periodUnitText.textContent = getPeriodUnitLabel(selectedPeriodUnit);
      periodControls.querySelectorAll('[data-period-unit]').forEach((button) => {
        const isSelected = String(button.dataset.periodUnit || '') === selectedPeriodUnit;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-selected', isSelected ? 'true' : 'false');
      });
    };
    const selectPeriodUnit = (unit) => {
      selectedPeriodUnit = unit === 'days' ? 'days' : 'forever';
      syncPeriodUi();
      closePeriodMenus();
    };

    const syncMatchedRetentionValues = () => {
      if (selectedRetentionStrategy !== 'match') return;
      const conditionValues = collectRequirementConditionValues();
      renderRetentionConditionRows(conditionValues);
      selectedRetentionMatchCount = selectedRequirementMatchCount;
      selectedRetentionMode = normalizeBonusLevelRequirementMode(selectedMode);
      selectedRetentionReferralMode = normalizeBonusLevelRequirementMode(selectedReferralMode);
      syncRetentionModeButton();
      syncRetentionReferralModeButton();
      syncRetentionConditionAvailability();
    };

    if (periodUnitTrigger && periodUnitMenu) {
      periodUnitTrigger.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const shouldOpen = periodUnitMenu.classList.contains('hidden');
        closePeriodMenus();
        if (!shouldOpen) return;
        periodUnitWrap?.classList.add('is-open');
        periodUnitMenu.classList.remove('hidden');
        periodUnitTrigger.setAttribute('aria-expanded', 'true');
      });
    }
    if (periodDotsBtn && periodInlineMenu) {
      periodDotsBtn.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const shouldOpen = periodInlineMenu.classList.contains('hidden');
        closePeriodMenus();
        if (!shouldOpen) return;
        periodInlineMenu.classList.remove('hidden');
        periodDotsBtn.setAttribute('aria-expanded', 'true');
      });
    }
    periodControls.querySelectorAll('[data-period-unit]').forEach((button) => {
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        selectPeriodUnit(String(button.dataset.periodUnit || 'forever'));
      });
    });
    requirementMatchCountTrigger?.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      const shouldOpen = requirementMatchCountMenu?.classList.contains('hidden');
      closePeriodMenus();
      if (!shouldOpen || !requirementMatchCountMenu) return;
      syncConditionAvailability();
      requirementMatchCountWrap?.classList.add('is-open');
      requirementMatchCountMenu.classList.remove('hidden');
      requirementMatchCountTrigger.setAttribute('aria-expanded', 'true');
    });
    requirementMatchCountMenu?.addEventListener('click', (event) => {
      const button = event.target.closest('[data-match-count]');
      if (!button) return;
      event.preventDefault();
      event.stopPropagation();
      selectedRequirementMatchCount = Math.max(1, normalizeNumberInputValue(button.dataset.matchCount, 1));
      syncConditionAvailability();
      syncMatchedRetentionValues();
      closePeriodMenus();
    });
    retentionMatchCountTrigger?.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (selectedRetentionStrategy !== 'custom') return;
      const shouldOpen = retentionMatchCountMenu?.classList.contains('hidden');
      closePeriodMenus();
      if (!shouldOpen || !retentionMatchCountMenu) return;
      syncRetentionConditionAvailability();
      retentionMatchCountWrap?.classList.add('is-open');
      retentionMatchCountMenu.classList.remove('hidden');
      retentionMatchCountTrigger.setAttribute('aria-expanded', 'true');
    });
    retentionMatchCountMenu?.addEventListener('click', (event) => {
      const button = event.target.closest('[data-retention-match-count]');
      if (!button) return;
      event.preventDefault();
      event.stopPropagation();
      selectedRetentionMatchCount = Math.max(1, normalizeNumberInputValue(button.dataset.retentionMatchCount, 1));
      syncRetentionConditionAvailability();
      closePeriodMenus();
    });
    syncPeriodUi();

    const actions = document.createElement('div');
    actions.className = 'bonus-range-editor-footer-actions';

    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'shop-checkout-benefits-promo-entry-btn';
    cancelBtn.textContent = '\u041e\u0442\u043c\u0435\u043d\u0430';
    cancelBtn.addEventListener('click', () => {
      closeBonusLevelRequirementsEditor();
    });
    actions.appendChild(cancelBtn);

    const saveBtn = document.createElement('button');
    saveBtn.type = 'button';
    saveBtn.className = 'shop-checkout-benefits-promo-entry-btn is-active';
    saveBtn.textContent = '\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c';
    saveBtn.addEventListener('click', () => {
      const periodInput = periodControls.querySelector('#bonusLevelRequirementModalPeriodInput');
      const retentionAmountInput = retentionSection.querySelector('#bonusLevelRetentionModalAmountInput');
      const retentionOrdersInput = retentionSection.querySelector('#bonusLevelRetentionModalOrdersInput');
      const retentionReferralsInput = retentionSection.querySelector('#bonusLevelRetentionModalReferralsInput');
      const retentionBonusAccruedInput = retentionSection.querySelector('#bonusLevelRetentionModalBonusAccruedInput');
      const retentionBonusRedeemedInput = retentionSection.querySelector('#bonusLevelRetentionModalBonusRedeemedInput');
      const { amountRaw, ordersRaw, referralsRaw, bonusAccruedRaw, bonusRedeemedRaw } = collectRequirementConditionValues();
      const periodRaw = String(periodInput?.value ?? '').trim();
      const retentionAmountRaw = String(retentionAmountInput?.value ?? '').trim();
      const retentionOrdersRaw = String(retentionOrdersInput?.value ?? '').trim();
      const retentionReferralsRaw = referralRequirementsEnabled ? String(retentionReferralsInput?.value ?? '').trim() : '';
      const retentionBonusAccruedRaw = String(retentionBonusAccruedInput?.value ?? '').trim();
      const retentionBonusRedeemedRaw = String(retentionBonusRedeemedInput?.value ?? '').trim();
      const amount = normalizeBonusLevelRequirementValue(amountRaw);
      const orders = normalizeBonusLevelRequirementValue(ordersRaw);
      const referrals = normalizeBonusLevelRequirementValue(referralsRaw);
      const bonusAccrued = normalizeBonusLevelRequirementValue(bonusAccruedRaw);
      const bonusRedeemed = normalizeBonusLevelRequirementValue(bonusRedeemedRaw);
      const periodDays = selectedPeriodUnit === 'days' ? normalizeBonusLevelRequirementValue(periodRaw) : null;
      const retentionAmount = normalizeBonusLevelRequirementValue(retentionAmountRaw);
      const retentionOrders = normalizeBonusLevelRequirementValue(retentionOrdersRaw);
      const retentionReferrals = normalizeBonusLevelRequirementValue(retentionReferralsRaw);
      const retentionBonusAccrued = normalizeBonusLevelRequirementValue(retentionBonusAccruedRaw);
      const retentionBonusRedeemed = normalizeBonusLevelRequirementValue(retentionBonusRedeemedRaw);
      const amountFilled = amountRaw !== '' && amount != null;
      const ordersFilled = ordersRaw !== '' && orders != null;
      const referralsFilled = referralsRaw !== '' && referrals != null;
      const bonusAccruedFilled = bonusAccruedRaw !== '' && bonusAccrued != null;
      const bonusRedeemedFilled = bonusRedeemedRaw !== '' && bonusRedeemed != null;
      const retentionAmountFilled = retentionAmountRaw !== '' && retentionAmount != null;
      const retentionOrdersFilled = retentionOrdersRaw !== '' && retentionOrders != null;
      const retentionReferralsFilled = retentionReferralsRaw !== '' && retentionReferrals != null;
      const retentionBonusAccruedFilled = retentionBonusAccruedRaw !== '' && retentionBonusAccrued != null;
      const retentionBonusRedeemedFilled = retentionBonusRedeemedRaw !== '' && retentionBonusRedeemed != null;
      const requirementFilledCount = [amountFilled, ordersFilled, referralsFilled, bonusAccruedFilled, bonusRedeemedFilled].filter(Boolean).length;
      const retentionFilledCount = [retentionAmountFilled, retentionOrdersFilled, retentionReferralsFilled, retentionBonusAccruedFilled, retentionBonusRedeemedFilled].filter(Boolean).length;
      const requirementMatchCount = Math.min(
        Math.max(1, selectedRequirementMatchCount),
        Math.max(1, requirementFilledCount)
      );
      const retentionMatchCount = Math.min(
        Math.max(1, selectedRetentionMatchCount || requirementMatchCount),
        Math.max(1, retentionFilledCount)
      );

      if (
        (amountRaw !== '' && amount == null)
        || (ordersRaw !== '' && orders == null)
        || (referralsRaw !== '' && referrals == null)
        || (bonusAccruedRaw !== '' && bonusAccrued == null)
        || (bonusRedeemedRaw !== '' && bonusRedeemed == null)
      ) {
        showBonusLevelRequirementsValidationMessage('\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438.');
        return;
      }
      if (!requirementFilledCount) {
        showBonusLevelRequirementsValidationMessage('\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0434\u043d\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u0435.');
        return;
      }
      if (selectedPeriodUnit === 'days' && periodDays == null) {
        showBonusLevelRequirementsValidationMessage('\u0423\u043a\u0430\u0436\u0438\u0442\u0435 \u043f\u0435\u0440\u0438\u043e\u0434 \u0432 \u0434\u043d\u044f\u0445 \u0438\u043b\u0438 \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 "\u0411\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e".');
        return;
      }
      if (selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom') {
        if (
          (retentionAmountRaw !== '' && retentionAmount == null)
          || (retentionOrdersRaw !== '' && retentionOrders == null)
          || (retentionReferralsRaw !== '' && retentionReferrals == null)
          || (retentionBonusAccruedRaw !== '' && retentionBonusAccrued == null)
          || (retentionBonusRedeemedRaw !== '' && retentionBonusRedeemed == null)
        ) {
          showBonusLevelRequirementsValidationMessage('\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438.');
          return;
        } else if (!retentionFilledCount) {
          showBonusLevelRequirementsValidationMessage('\u0414\u043b\u044f \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u0443\u0440\u043e\u0432\u043d\u044f \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0434\u043d\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u0435.');
          return;
        }
      }

      const nextPatch = {
        requirementAmount: amountFilled ? amount : null,
        requirementMode: normalizeBonusLevelRequirementMode(selectedMode),
        requirementOrders: ordersFilled ? orders : null,
        requirementReferralMode: referralRequirementsEnabled ? normalizeBonusLevelRequirementMode(selectedReferralMode) : 'and',
        requirementReferrals: referralRequirementsEnabled && referralsFilled ? referrals : null,
        requirementBonusAccrued: bonusAccruedFilled ? bonusAccrued : null,
        requirementBonusRedeemed: bonusRedeemedFilled ? bonusRedeemed : null,
        requirementMatchCount,
        requirementPeriodDays: selectedPeriodUnit === 'days' ? periodDays : null,
        retentionStrategy: selectedPeriodUnit === 'days' ? normalizeBonusLevelRetentionStrategy(selectedRetentionStrategy) : 'match',
        retentionAmount: selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' && retentionAmountFilled ? retentionAmount : null,
        retentionMode: normalizeBonusLevelRequirementMode(selectedRetentionMode),
        retentionOrders: selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' && retentionOrdersFilled ? retentionOrders : null,
        retentionReferralMode: referralRequirementsEnabled ? normalizeBonusLevelRequirementMode(selectedRetentionReferralMode) : 'and',
        retentionReferrals: referralRequirementsEnabled && selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' && retentionReferralsFilled ? retentionReferrals : null,
        retentionBonusAccrued: selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' && retentionBonusAccruedFilled ? retentionBonusAccrued : null,
        retentionBonusRedeemed: selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' && retentionBonusRedeemedFilled ? retentionBonusRedeemed : null,
        retentionMatchCount: selectedPeriodUnit === 'days' && selectedRetentionStrategy === 'custom' ? retentionMatchCount : requirementMatchCount,
      };
      applyBonusLevelEditorDraftPatch(nextPatch);
      updateBonusLevelInCollections(current.id, (level) => ({
        ...level,
        ...nextPatch,
      }));
      if (state.bonusCardsEditing !== true) persistBonusCardsStorageSoon();
      renderBonusLevels();
      renderBonusLevelInfo();
      closeBonusLevelRequirementsEditor();
    });
    actions.appendChild(saveBtn);

    frame.footerEl.appendChild(actions);
  }

  function closeBonusLevelRangeEditor() {
    const { backdrop } = getClientBenefitsOverlayElements();
    if (backdrop) backdrop.classList.remove('bonus-range-editor-overlay');
    window.AdminBenefitsModal?.hide();
  }

  function collectBonusRangeEditorRows(rowsRoot) {
    if (!(rowsRoot instanceof Element)) return [];
    const rows = Array.from(rowsRoot.querySelectorAll('.bonus-range-editor-input-row'));
    return sanitizeBonusRangeRows(rows.map((row) => ({
      amount: normalizeBonusRangeAmount(row.querySelector('[data-bonus-range-field="amount"]')?.value, 0),
      percent: normalizeBonusRangePercent(row.querySelector('[data-bonus-range-field="percent"]')?.value, 0),
    })));
  }

  function appendBonusRangeEditorRow(rowsRoot, row = null) {
    if (!(rowsRoot instanceof Element)) return null;
    const nextRow = row && typeof row === 'object' ? row : {};
    const rowEl = document.createElement('div');
    rowEl.className = 'bonus-range-editor-input-row';
    rowEl.innerHTML = `
      <input
        class="control bonus-range-editor-input"
        type="number"
        min="0"
        step="1"
        placeholder="Сумма заказа, ₽"
        data-bonus-range-field="amount"
        value="${escapeHtml(String(normalizeBonusRangeAmount(nextRow.amount, 0) || ''))}"
      />
      <input
        class="control bonus-range-editor-input bonus-range-percent-input"
        type="number"
        min="0"
        max="100"
        step="0.1"
        placeholder="Бонус, %"
        data-bonus-range-field="percent"
        value="${escapeHtml(String(normalizeBonusRangePercent(nextRow.percent, 0) || ''))}"
      />
      <button
        type="button"
        class="bonus-range-editor-delete-btn"
        aria-label="Удалить порог"
        title="Удалить порог"
      >
        <i class="fas fa-times" aria-hidden="true"></i>
      </button>
    `;
    const deleteBtn = rowEl.querySelector('.bonus-range-editor-delete-btn');
    if (deleteBtn) {
      deleteBtn.addEventListener('click', () => {
        rowEl.remove();
      });
    }
    rowsRoot.appendChild(rowEl);
    return rowEl;
  }

  function openBonusLevelRangeEditor() {
    if (!isBonusLevelEditorActive()) return;
    const current = getActiveBonusLevelForInfo();
    if (!current) return;

    window.AdminBenefitsModal?.show({
      title: 'Пороги',
      showBack: false,
      showModeToggle: false,
      onClose: closeBonusLevelRangeEditor,
    });

    const { backdrop, body } = getClientBenefitsOverlayElements();
    if (!body) return;
    if (backdrop) backdrop.classList.add('bonus-range-editor-overlay');
    body.innerHTML = '';

    const frame = window.AdminBenefitsModal?.createScrollableFrame({ hasFooter: true });
    if (!frame?.root || !frame.scrollEl || !frame.footerEl) return;
    body.appendChild(frame.root);

    const shell = document.createElement('div');
    shell.className = 'bonus-range-editor-modal';
    frame.scrollEl.appendChild(shell);

    const title = document.createElement('div');
    title.className = 'bonus-range-editor-title';
    title.textContent = 'Дополнительные бонусы за сумму заказа';
    shell.appendChild(title);

    const note = document.createElement('div');
    note.className = 'bonus-range-editor-row';
    note.textContent = 'Укажите сумму заказа и процент бонуса для каждого порога.';
    shell.appendChild(note);

    const rowsRoot = document.createElement('div');
    rowsRoot.className = 'bonus-range-editor-rows';
    shell.appendChild(rowsRoot);

    const sourceRows = Array.isArray(current.orderBonusRanges) && current.orderBonusRanges.length
      ? current.orderBonusRanges
      : [{ amount: 0, percent: 0 }];
    sourceRows.forEach((row) => appendBonusRangeEditorRow(rowsRoot, row));

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'bonus-range-editor-add-btn';
    addBtn.textContent = '+';
    addBtn.setAttribute('aria-label', 'Добавить порог');
    addBtn.addEventListener('click', () => {
      appendBonusRangeEditorRow(rowsRoot, { amount: 0, percent: 0 });
    });
    shell.appendChild(addBtn);

    const actions = document.createElement('div');
    actions.className = 'bonus-range-editor-footer-actions';

    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'shop-checkout-benefits-promo-entry-btn';
    cancelBtn.textContent = 'Отмена';
    cancelBtn.addEventListener('click', () => {
      closeBonusLevelRangeEditor();
    });
    actions.appendChild(cancelBtn);

    const saveBtn = document.createElement('button');
    saveBtn.type = 'button';
    saveBtn.className = 'shop-checkout-benefits-promo-entry-btn is-active';
    saveBtn.textContent = 'Сохранить';
    saveBtn.addEventListener('click', () => {
      const nextRows = collectBonusRangeEditorRows(rowsRoot);
      applyBonusLevelEditorDraftPatch({
        orderBonusRanges: nextRows,
      });
      updateBonusLevelInCollections(current.id, (level) => ({
        ...level,
        orderBonusRanges: nextRows,
      }));
      if (state.bonusCardsEditing !== true) persistBonusCardsStorageSoon();
      renderBonusLevels();
      renderBonusLevelInfo();
      closeBonusLevelRangeEditor();
    });
    actions.appendChild(saveBtn);

    frame.footerEl.appendChild(actions);
  }

  function getBonusCategoryGroupById(groupId) {
    const id = Number(groupId || 0);
    if (!(id > 0)) return null;
    const groups = state.bonusSettingsEditing ? state.bonusCategoryGroupsDraft : state.bonusCategoryGroups;
    return (Array.isArray(groups) ? groups : []).find((group) => Number(group?.id || 0) === id) || null;
  }

  function getActiveBonusCategoryGroup() {
    const groups = state.bonusSettingsEditing ? state.bonusCategoryGroupsDraft : state.bonusCategoryGroups;
    const monthNumber = new Date().getMonth() + 1;
    return (Array.isArray(groups) ? groups : []).find((group) => Number(group?.monthNumber || group?.month_number || 0) === monthNumber) || null;
  }

  function getBonusLevelFavoriteCategoryConfig(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const selectedGroup = getActiveBonusCategoryGroup();
    return {
      group: selectedGroup,
      bonusPercent: selectedGroup ? normalizeNumberInputValue(selectedGroup.favoriteCategoriesBonusPercent, 0) : 0,
      limit: Math.max(0, Math.floor(Number(current?.favoriteCategoriesLimit || 0))),
      categoryIds: selectedGroup ? getBonusCategoryGroupCategoryIds(selectedGroup) : [],
    };
  }

  function formatBonusLevelFavoriteCategoryPercentText(level = null) {
    const { group: selectedGroup } = getBonusLevelFavoriteCategoryConfig(level);
    const percents = normalizeBonusCategoryGroupItems(
      selectedGroup?.categoryItems,
      selectedGroup?.favoriteCategoryIds,
      selectedGroup?.favoriteCategoriesBonusPercent
    )
      .map((item) => normalizeNumberInputValue(item.bonusPercent, 0))
      .filter((value) => value > 0);
    if (!percents.length) return '0%';
    const min = Math.min(...percents);
    const max = Math.max(...percents);
    if (Math.abs(max - min) < 0.0001) return `${formatBonusRangePercentValue(max)}%`;
    return `${formatBonusRangePercentValue(min)}-${formatBonusRangePercentValue(max)}%`;
  }

  function formatBonusLevelFavoriteCategoriesHelpText(level = null) {
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const { group: selectedGroup, bonusPercent, limit, categoryIds: favoriteCategoryIds } = getBonusLevelFavoriteCategoryConfig(current);

    if (!(bonusPercent > 0) && !(limit > 0)) {
      return 'Дополнительный бонус за любимые категории не настроен.';
    }
    const lines = [];
    if (selectedGroup) {
      lines.push(`Группа: ${escapeHtml(selectedGroup.title)}`);
    }
    if (bonusPercent > 0) lines.push(`Кэшбек: +${bonusPercent}%`);
    if (limit > 0) lines.push(`Количество категорий: ${limit}`);
    if (favoriteCategoryIds.length) {
      const categoryTitles = favoriteCategoryIds.map((id) => {
        const category = (state.catalogCategories || []).find((entry) => Number(entry?.id || 0) === id);
        return String(category?.title || `Категория #${id}`).trim();
      });
      lines.push(`Категории: ${categoryTitles.join(', ')}`);
    }
    return lines.join('\n');
  }

  function renderBonusFavoriteCategoryIconsHtml(categoryIds = []) {
    const selectedIds = normalizeBonusLevelFavoriteCategoryIds(categoryIds);
    const visibleCount = Math.min(selectedIds.length, 4);
    let html = '';
    for (let i = 0; i < visibleCount; i += 1) {
      const categoryId = selectedIds[i];
      const category = (state.catalogCategories || []).find((entry) => Number(entry?.id || 0) === Number(categoryId));
      const titleText = String(category?.title || `Категория #${categoryId}`).trim();
      const photo = getDiscountEntityPhoto({ type: 'category', id: categoryId });
      const icon = String(category?.icon || '').trim();
      let inner = '';
      if (photo) {
        inner = `<img src="${escapeHtml(photo)}" alt="${escapeHtml(titleText)}">`;
      } else if (icon && isDiscountEntityImageUrl(icon)) {
        inner = `<img src="${escapeHtml(icon)}" alt="${escapeHtml(titleText)}">`;
      } else if (icon) {
        inner = `<i class="${escapeHtml(icon)}" aria-hidden="true"></i>`;
      } else {
        inner = '<i class="fas fa-tag" aria-hidden="true"></i>';
      }
      html += `<span class="bonus-level-favorite-category-icon" title="${escapeHtml(titleText)}">${inner}</span>`;
    }
    if (selectedIds.length > visibleCount) {
      html += `<span class="bonus-level-favorite-category-icon">+${selectedIds.length - visibleCount}</span>`;
    }
    return html;
  }

  function renderBonusLevelFavoriteCategoryIcons(level = null) {
    if (!bonusLevelFavoriteCategoriesIcons || !bonusLevelFavoriteCategoriesPill) return;
    const current = level && typeof level === 'object' ? level : getActiveBonusLevelForInfo();
    const isEditing = isBonusLevelEditorActive(current?.id);
    
    const groupId = Number(current?.favoriteCategoryGroupId || 0);
    const { bonusPercent, limit, categoryIds: selectedIds } = getBonusLevelFavoriteCategoryConfig(current);

    bonusLevelFavoriteCategoriesIcons.innerHTML = '';
    
    // Check if empty
    if (!groupId && !selectedIds.length && !(limit > 0)) {
      bonusLevelFavoriteCategoriesIcons.innerHTML = `
        <div class="bonus-level-favorite-categories-plus" style="width: 100%; display: flex; justify-content: center; align-items: center; cursor: ${isEditing ? 'pointer' : 'default'};">
          <i class="fas fa-plus"></i>
        </div>
      `;
      bonusLevelFavoriteCategoriesPill.classList.add('is-empty');
      // Hide standard actions if empty
      const actions = bonusLevelFavoriteCategoriesPill.querySelector('.bonus-level-range-pill-actions');
      if (actions) actions.style.display = 'none';
      
      if (isEditing) {
        bonusLevelFavoriteCategoriesIcons.onclick = (e) => {
          e.preventDefault();
          e.stopPropagation();
          openBonusLevelFavoriteCategoryGroupPicker();
        };
      } else {
        bonusLevelFavoriteCategoriesIcons.onclick = null;
      }
      return;
    }

    bonusLevelFavoriteCategoriesPill.classList.remove('is-empty');
    const actions = bonusLevelFavoriteCategoriesPill.querySelector('.bonus-level-range-pill-actions');
    if (actions) actions.style.display = '';
    bonusLevelFavoriteCategoriesIcons.onclick = null;

    const visibleSourceCount = selectedIds.length || limit;
    const visibleCount = Math.min(visibleSourceCount, 4);
    for (let i = 0; i < visibleCount; i += 1) {
      const badge = document.createElement('span');
      badge.className = 'bonus-level-favorite-category-icon';
      const categoryId = selectedIds[i];
      if (categoryId) {
        const photo = getDiscountEntityPhoto({ type: 'category', id: categoryId });
        const category = (state.catalogCategories || []).find((entry) => Number(entry?.id || 0) === Number(categoryId));
        const titleText = String(category?.title || `Категория #${categoryId}`).trim();
        badge.title = titleText;
        const icon = String(category?.icon || '').trim();
        if (photo) {
          badge.innerHTML = `<img src="${escapeHtml(photo)}" alt="${escapeHtml(titleText)}">`;
        } else if (icon && isDiscountEntityImageUrl(icon)) {
          badge.innerHTML = `<img src="${escapeHtml(icon)}" alt="${escapeHtml(titleText)}">`;
        } else if (icon) {
          badge.innerHTML = `<i class="${escapeHtml(icon)}" aria-hidden="true"></i>`;
        } else {
          badge.innerHTML = '<i class="fas fa-tag" aria-hidden="true"></i>';
        }
      } else {
        badge.innerHTML = '<i class="fas fa-tag" aria-hidden="true"></i>';
      }
      bonusLevelFavoriteCategoriesIcons.appendChild(badge);
    }
    if (visibleSourceCount > visibleCount) {
      const rest = document.createElement('span');
      rest.className = 'bonus-level-favorite-category-icon';
      rest.textContent = `+${visibleSourceCount - visibleCount}`;
      bonusLevelFavoriteCategoriesIcons.appendChild(rest);
    }
  }

  function closeBonusLevelFavoriteCategoriesEditor() {
    const { backdrop } = getClientBenefitsOverlayElements();
    if (backdrop) backdrop.classList.remove('bonus-range-editor-overlay');
    window.AdminBenefitsModal?.hide();
  }

