  async function saveReferralEditMode() {
    const nextEnabled = state.referralProgramEnabledDraft === true;
    const nextLevels = (Array.isArray(state.bonusReferralLevelsDraft) ? state.bonusReferralLevelsDraft : []).map((level) => ({ ...level }));
    const nextFirstPurchaseReward = normalizeBonusReferralRewardValue(state.referralFirstPurchaseRewardDraft, 0);
    const nextRegistrationReward = normalizeBonusReferralRewardValue(state.referralRegistrationRewardDraft, 0);
    const nextCardMainColor = normalizeHexColor(state.referralCardMainColorDraft, '#f3f4f6');
    const nextCardBaseColor = normalizeHexColor(state.referralCardBaseColorDraft, '#d1d5db');
    const nextCardContentColor = normalizeHexColor(state.referralCardContentColorDraft, '#64748b');
    const nextCardButtonColor = normalizeHexColor(state.referralCardButtonColorDraft, '#ff6a00');
    const nextCardQrEnabled = state.referralCardQrEnabledDraft !== false;
    const nextCardTitleBackgroundEnabled = state.referralCardTitleBackgroundEnabledDraft !== false;
    const nextCardTitleBackgroundColor = normalizeHexColor(state.referralCardTitleBackgroundColorDraft, '#ffffff');
    const nextCardTitleBackgroundOpacity = normalizeBannerOpacity(state.referralCardTitleBackgroundOpacityDraft, 90);
    setBonusConfigSaving(true, '\u041f\u043e\u0434\u043e\u0436\u0434\u0438\u0442\u0435, \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u0440\u0435\u0444\u0435\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443...');
    try {
      await persistBonusCardsStorage({
        referralProgramEnabled: nextEnabled,
        referralFirstPurchaseReward: nextFirstPurchaseReward,
        referralRegistrationReward: nextRegistrationReward,
        referralCardMainColor: nextCardMainColor,
        referralCardBaseColor: nextCardBaseColor,
        referralCardContentColor: nextCardContentColor,
        referralCardButtonColor: nextCardButtonColor,
        referralCardQrEnabled: nextCardQrEnabled,
        referralCardTitleBackgroundEnabled: nextCardTitleBackgroundEnabled,
        referralCardTitleBackgroundColor: nextCardTitleBackgroundColor,
        referralCardTitleBackgroundOpacity: nextCardTitleBackgroundOpacity,
        referralLevels: nextLevels,
      });
    } catch (err) {
      setBonusConfigSaving(false);
      reportBonusConfigSaveError(err);
      return;
    }
    state.referralProgramEnabled = nextEnabled;
    state.referralFirstPurchaseReward = nextFirstPurchaseReward;
    state.referralRegistrationReward = nextRegistrationReward;
    state.referralCardMainColor = nextCardMainColor;
    state.referralCardBaseColor = nextCardBaseColor;
    state.referralCardContentColor = nextCardContentColor;
    state.referralCardButtonColor = nextCardButtonColor;
    state.referralCardQrEnabled = nextCardQrEnabled;
    state.referralCardTitleBackgroundEnabled = nextCardTitleBackgroundEnabled;
    state.referralCardTitleBackgroundColor = nextCardTitleBackgroundColor;
    state.referralCardTitleBackgroundOpacity = nextCardTitleBackgroundOpacity;
    state.bonusReferralLevels = nextLevels;
    state.referralEditing = false;
    syncBonusToolbarState();
    renderBonusReferralRightHome();
    renderBonusReferralLevelsSettings();
    renderBonusReferralLevels();
    setBonusConfigSaving(false);
  }

  function renderBannerList() {
    if (!elBannersList) return;
    elBannersList.innerHTML = '';

    const drafts = getBannerDraftsByType();
    if (!drafts.length) {
      if (elBannersEmptyHint) elBannersEmptyHint.classList.remove('hidden');
      return;
    }
    if (elBannersEmptyHint) elBannersEmptyHint.classList.add('hidden');

    drafts.forEach((banner) => {
      const meta = getBannerTypeMeta(banner.type);
      const isPlaced = isBannerPlaced(banner.id, banner.type);
      const row = document.createElement('div');
      row.className = 'order-row';
      row.draggable = true;
      row.dataset.bannerId = banner.id;
      row.setAttribute('role', 'button');
      row.setAttribute('tabindex', '0');
      row.classList.toggle('is-banner-placed', isPlaced);
      row.classList.toggle('is-active', String(state.activeBannerId || '') === String(banner.id));
      row.innerHTML = `
        <div class="order-icon"><i class="${escapeHtml(meta.icon)}"></i></div>
        <div class="order-mid">
          <strong>${escapeHtml(banner.title)}</strong>
          <div class="muted">${escapeHtml(meta.singular)} • Черновик</div>
        </div>
        ${isPlaced ? '<div class="banner-row-badge">Размещён</div>' : ''}
      `;
      row.addEventListener('click', () => openBannerTab(banner.id));
      row.addEventListener('keydown', (event) => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        openBannerTab(banner.id);
      });
      row.addEventListener('dragstart', (event) => {
        state.bannerDragState = { source: 'list', bannerId: banner.id };
        row.classList.add('is-dragging');
        if (event.dataTransfer) {
          event.dataTransfer.effectAllowed = 'move';
          event.dataTransfer.setData('text/plain', String(banner.id));
        }
      });
      row.addEventListener('dragend', () => {
        clearBannerDragState();
      });
      elBannersList.appendChild(row);
    });
  }

  function reorderBannerPlacement(fromIndex, toIndex) {
    const current = [...getBannerPlacementsByType()];
    if (fromIndex < 0 || toIndex < 0 || fromIndex === toIndex) return;
    if (fromIndex >= current.length || toIndex >= current.length) return;
    const [moved] = current.splice(fromIndex, 1);
    current.splice(toIndex, 0, moved);
    setBannerPlacementsByType(state.activeBannerType, current);
    renderBannerPlacement();
  }

  function renderBannerPlacement() {
    if (!elBannersPlacementTrack) return;
    elBannersPlacementTrack.innerHTML = '';

    const placedDrafts = getPlacedBannerDraftsByType();
    const placementBody = elBannersPlacementZone?.querySelector('.banners-placement-body');
    const placementTrackHeight = Math.round(elBannersPlacementTrack.clientHeight || 0);
    const placementBodyHeight = Math.round(placementBody?.clientHeight || 0);
    const cardHeight = Math.max(104, placementTrackHeight || placementBodyHeight || 0);
    if (elBannersPlacementZone) {
      elBannersPlacementZone.classList.toggle('is-empty', placedDrafts.length === 0);
    }

    placedDrafts.forEach((banner, index) => {
      const meta = getBannerTypeMeta(banner.type);
      const ratio = getBannerAspectRatioDimensions(banner.aspectRatio, banner.type);
      const cardWidth = Math.max(132, Math.round(cardHeight * (ratio.width / ratio.height)));
      const previewPhoto = Array.isArray(banner.photos) ? String(banner.photos[0] || '').trim() : '';
      const card = document.createElement('div');
      card.className = 'banner-placement-card';
      const titlePosition = normalizeBannerTitlePosition(banner.titlePosition);
      const showTitleOnCard = banner.showTitleOnCard === true && String(banner.title || '').trim() !== '';
      card.draggable = true;
      card.dataset.bannerId = banner.id;
      card.dataset.placementIndex = String(index);
      card.style.height = `${cardHeight}px`;
      card.style.width = `${cardWidth}px`;
      card.style.flex = `0 0 ${cardWidth}px`;
      const mainMarkup = `
        <div class="banner-placement-card-main">
          ${previewPhoto
            ? `<img class="banner-placement-card-preview" src="${escapeHtml(previewPhoto)}" alt="" style="object-fit:${banner?.stretchPhoto === true ? 'cover' : 'contain'};">`
            : `<div class="banner-placement-card-icon"><i class="${escapeHtml(meta.icon)}"></i></div>`}
        </div>
      `;
      const titleStyleParts = [
        `color:${escapeHtml(banner.titleColor || '#1f2937')}`,
        banner.titleBackgroundEnabled === false
          ? 'background:transparent'
          : `background:${buildBannerTitleBackgroundColor(banner.titleBackgroundColor || '#ffffff', banner.titleBackgroundOpacity)}`,
      ];
      const titleMarkup = showTitleOnCard
        ? `<div class="banner-placement-card-display-title" style="${titleStyleParts.join(';')}">${escapeHtml(banner.title)}</div>`
        : '';
      card.innerHTML = `
        <div class="banner-placement-card-stack ${showTitleOnCard && titlePosition === 'bottom' ? 'is-title-bottom' : 'is-title-top'}">
          ${showTitleOnCard && titlePosition !== 'bottom' ? titleMarkup : ''}
          ${mainMarkup}
          ${showTitleOnCard && titlePosition === 'bottom' ? titleMarkup : ''}
        </div>
      `.trim();

      card.addEventListener('click', () => openBannerTab(banner.id));
      card.addEventListener('dragstart', (event) => {
        state.bannerDragState = { source: 'placement', bannerId: banner.id, index };
        card.classList.add('is-dragging');
        if (event.dataTransfer) {
          event.dataTransfer.effectAllowed = 'move';
          event.dataTransfer.setData('text/plain', String(banner.id));
        }
      });
      card.addEventListener('dragend', () => {
        clearBannerDragState();
      });
      card.addEventListener('dragover', (event) => {
        if (!state.bannerDragState) return;
        event.preventDefault();
        if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        card.classList.add('is-drag-over');
      });
      card.addEventListener('dragleave', () => {
        card.classList.remove('is-drag-over');
      });
      card.addEventListener('drop', (event) => {
        event.preventDefault();
        card.classList.remove('is-drag-over');
        if (!state.bannerDragState) return;
        if (state.bannerDragState.source === 'placement') {
          reorderBannerPlacement(state.bannerDragState.index, index);
        } else if (state.bannerDragState.source === 'list') {
          addBannerToPlacement(state.bannerDragState.bannerId, index);
        }
        clearBannerDragState();
      });

      elBannersPlacementTrack.appendChild(card);
    });

    const addCard = document.createElement('button');
    addCard.type = 'button';
    addCard.className = 'banner-placement-card banner-placement-add-card';
    addCard.setAttribute('aria-label', 'Добавить баннеры в размещение');
    addCard.setAttribute('title', 'Добавить баннеры в размещение');
    addCard.style.height = `${cardHeight}px`;
    addCard.innerHTML = `
      <span class="banner-placement-add-icon"><i class="fas fa-plus"></i></span>
      <span class="banner-placement-add-label">Добавить</span>
    `;
    addCard.addEventListener('click', () => openBannerPicker());
    addCard.addEventListener('dragover', (event) => {
      if (!state.bannerDragState) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      addCard.classList.add('is-drag-over');
    });
    addCard.addEventListener('dragleave', () => {
      addCard.classList.remove('is-drag-over');
    });
    addCard.addEventListener('drop', (event) => {
      event.preventDefault();
      addCard.classList.remove('is-drag-over');
      if (!state.bannerDragState) return;
      if (state.bannerDragState.source === 'placement' && placedDrafts.length) {
        reorderBannerPlacement(state.bannerDragState.index, placedDrafts.length - 1);
      } else if (state.bannerDragState.source === 'list') {
        addBannerToPlacement(state.bannerDragState.bannerId);
      }
      clearBannerDragState();
    });
    elBannersPlacementTrack.appendChild(addCard);

  }

  if (elBannersList) {
    elBannersList.addEventListener('dragover', (event) => {
      if (state.bannerDragState?.source !== 'placement') return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      elBannersList.classList.add('is-drag-over');
    });
    elBannersList.addEventListener('dragleave', (event) => {
      if (event.currentTarget !== event.target && elBannersList.contains(event.relatedTarget)) return;
      elBannersList.classList.remove('is-drag-over');
    });
    elBannersList.addEventListener('drop', (event) => {
      if (state.bannerDragState?.source !== 'placement') return;
      event.preventDefault();
      elBannersList.classList.remove('is-drag-over');
      removeBannerFromPlacement(state.bannerDragState.bannerId);
      clearBannerDragState();
    });
  }

  function closeBannerPicker() {
    state.bannerPickerOpen = false;
    state.bannerPickerDraftSelection = new Set();
    if (elBannerPickerOverlay) {
      elBannerPickerOverlay.classList.add('hidden');
      elBannerPickerOverlay.setAttribute('aria-hidden', 'true');
    }
  }

  function openBannerPicker() {
    if (state.currentView !== 'banners') return;
    state.bannerPickerOpen = true;
    state.bannerPickerDraftSelection = new Set(getBannerPlacementsByType());
    renderBannerPicker();
  }

  function renderBannerPicker() {
    if (!elBannerPickerOverlay || !elBannerPickerList) return;
    if (!state.bannerPickerOpen) {
      elBannerPickerOverlay.classList.add('hidden');
      elBannerPickerOverlay.setAttribute('aria-hidden', 'true');
      return;
    }

    const meta = getBannerTypeMeta(state.activeBannerType);
    const drafts = getBannerDraftsByType();
    if (elBannerPickerTitle) {
      elBannerPickerTitle.textContent = `Размещение: ${meta.title}`;
    }
    if (elBannerPickerSubtitle) {
      elBannerPickerSubtitle.textContent = 'Выберите один или несколько баннеров для верхнего блока.';
    }

    elBannerPickerList.innerHTML = '';
    if (elBannerPickerEmptyHint) {
      elBannerPickerEmptyHint.classList.toggle('hidden', drafts.length > 0);
    }

    drafts.forEach((banner) => {
      const selected = state.bannerPickerDraftSelection.has(String(banner.id));
      const row = document.createElement('button');
      row.type = 'button';
      row.className = 'banner-picker-row';
      row.classList.toggle('is-selected', selected);
      row.dataset.bannerId = banner.id;
      row.innerHTML = `
        <span class="banner-picker-check"><i class="fas fa-check"></i></span>
        <span class="banner-picker-row-copy">
          <span class="banner-picker-row-title">${escapeHtml(banner.title)}</span>
          <span class="banner-picker-row-meta">${escapeHtml(meta.singular)} • Черновик</span>
        </span>
      `;
      row.addEventListener('click', () => {
        const bannerId = String(banner.id);
        if (state.bannerPickerDraftSelection.has(bannerId)) {
          state.bannerPickerDraftSelection.delete(bannerId);
        } else {
          state.bannerPickerDraftSelection.add(bannerId);
        }
        renderBannerPicker();
      });
      elBannerPickerList.appendChild(row);
    });

    if (elBannerPickerSaveBtn) {
      elBannerPickerSaveBtn.disabled = false;
    }
    elBannerPickerOverlay.classList.remove('hidden');
    elBannerPickerOverlay.setAttribute('aria-hidden', 'false');
  }

  function saveBannerPickerSelection() {
    const drafts = getBannerDraftsByType();
    const current = getBannerPlacementsByType();
    const selection = state.bannerPickerDraftSelection instanceof Set
      ? state.bannerPickerDraftSelection
      : new Set();
    const selectedIds = new Set(
      [...selection]
        .map((id) => String(id || '').trim())
        .filter(Boolean)
    );
    const kept = current.filter((id) => selectedIds.has(String(id)));
    const additions = drafts
      .map((banner) => String(banner.id))
      .filter((id) => selectedIds.has(id) && !kept.includes(id));
    setBannerPlacementsByType(state.activeBannerType, [...kept, ...additions]);
    renderBannerFilters();
    renderBannerPlacement();
    renderBannerList();
    closeBannerPicker();
  }

  function adjustBannerDescriptionHeight() {
    if (!bannerDescriptionInput) return;
    bannerDescriptionInput.style.height = 'auto';
    bannerDescriptionInput.style.height = `${bannerDescriptionInput.scrollHeight}px`;
  }

  function adjustBonusLevelDescriptionHeight() {
    if (!bonusLevelDescriptionInput) return;
    bonusLevelDescriptionInput.style.height = 'auto';
    bonusLevelDescriptionInput.style.height = `${bonusLevelDescriptionInput.scrollHeight}px`;
  }

  function renderBannerInfo(banner) {
    const current = banner && typeof banner === 'object' ? banner : getBannerDraftById(state.activeBannerId);
    const isEditing = !!current && String(state.editingBannerId || '') === String(current.id || '');
    if (bannerInfoTitle) {
      bannerInfoTitle.textContent = '';
    }
    if (bannerInfoMeta) {
      bannerInfoMeta.textContent = '';
    }
    if (bannerInfoText) {
      bannerInfoText.textContent = '';
    }
    if (bannerTitleInput) {
      bannerTitleInput.value = current?.title || '';
      bannerTitleInput.disabled = !isEditing;
    }
    if (bannerDescriptionInput) {
      bannerDescriptionInput.value = current?.description || '';
      bannerDescriptionInput.disabled = !isEditing;
      adjustBannerDescriptionHeight();
    }
    if (bannerTitleOnCardSwitch) {
      bannerTitleOnCardSwitch.checked = current?.showTitleOnCard === true;
      bannerTitleOnCardSwitch.disabled = !isEditing;
    }
    if (bannerTitleColorInput) {
      bannerTitleColorInput.value = current?.titleColor || '#1f2937';
      bannerTitleColorInput.disabled = !isEditing;
    }
    if (bannerTitleBackgroundSwitch) {
      bannerTitleBackgroundSwitch.checked = current?.titleBackgroundEnabled !== false;
      bannerTitleBackgroundSwitch.disabled = !isEditing;
    }
    if (bannerTitleBackgroundColorInput) {
      bannerTitleBackgroundColorInput.value = current?.titleBackgroundColor || '#ffffff';
      bannerTitleBackgroundColorInput.disabled = !isEditing || (current?.titleBackgroundEnabled === false);
    }
    if (bannerTitleBackgroundOpacityInput) {
      const opacity = normalizeBannerOpacity(current?.titleBackgroundOpacity, 90);
      bannerTitleBackgroundOpacityInput.value = String(opacity);
      bannerTitleBackgroundOpacityInput.disabled = !isEditing || (current?.titleBackgroundEnabled === false);
      if (bannerTitleBackgroundOpacityValue) {
        bannerTitleBackgroundOpacityValue.textContent = `${opacity}%`;
      }
    }
    if (bannerPhotoStretchSwitch) {
      bannerPhotoStretchSwitch.checked = current?.stretchPhoto === true;
      bannerPhotoStretchSwitch.disabled = !isEditing;
    }
    renderBannerAspectRatioPicker(current, isEditing);
    renderBannerPhotoRail(current, isEditing);
    if (bannerInfoEditBtn) {
      bannerInfoEditBtn.textContent = isEditing ? 'Сохранить' : 'Редактировать';
    }
  }

  function openBannerTab(bannerId) {
    const banner = getBannerDraftById(bannerId);
    if (!banner) return;

    ensureTab({
      type: 'banner',
      id: banner.id,
      title: banner.title,
      onActivate: () => activateBannerTab(banner.id),
    });
  }

  function activateBannerTab(bannerId) {
    const banner = getBannerDraftById(bannerId);
    if (!banner) return;
    state.activeBannerType = banner.type;
    state.activeBannerId = banner.id;
    if (String(state.editingBannerId || '') !== String(banner.id)) {
      state.editingBannerId = null;
    }
    renderBannerInfo(banner);
    renderBannerFilters();
    renderBannerPlacement();
    renderBannerList();
    updateRightPanel();
  }

  function createBannerDraft(type = state.activeBannerType) {
    const meta = getBannerTypeMeta(type);
    const draft = {
      id: `banner_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      type: meta.key,
      title: meta.tabTitle,
      description: '',
      createdAt: Date.now(),
      aspectRatio: getDefaultBannerAspectRatio(meta.key),
      showTitleOnCard: false,
      titlePosition: 'top',
      titleColor: '#1f2937',
      titleBackgroundEnabled: true,
      titleBackgroundColor: '#ffffff',
      titleBackgroundOpacity: 90,
      photos: [],
      photoSizes: {},
      stretchPhoto: false,
    };
    state.bannersDrafts = sanitizeBannerDrafts([draft, ...state.bannersDrafts]);
    state.activeBannerType = meta.key;
    state.editingBannerId = draft.id;
    persistBannerStorage();
    renderBannerFilters();
    renderBannerPlacement();
    renderBannerList();
    if (state.bannerPickerOpen) {
      renderBannerPicker();
    }
    openBannerTab(draft.id);
  }

  async function deleteActiveBanner() {
    const banner = getBannerDraftById(state.activeBannerId);
    if (!banner) return;

    state.bannersDrafts = sanitizeBannerDrafts(
      state.bannersDrafts.filter((item) => String(item?.id || '') !== String(banner.id))
    );
    state.bannerPlacements = sanitizeBannerPlacements(state.bannerPlacements, state.bannersDrafts);
    persistBannerStorage();
    renderBannerFilters();
    renderBannerPlacement();
    renderBannerList();
    if (state.bannerPickerOpen) {
      renderBannerPicker();
    }
    await closeTab(buildTabKey('banner', banner.id));
  }

  async function openDiscountTab(discount) {
    if (state.currentView !== 'discounts') {
      switchView('discounts');
    }

    const tabKey = buildTabKey('discount', discount.id);
    let existing = tabsState.tabs.find(t => t.key === tabKey);
    if (!existing) {
      tabsState.tabs.push({
        key: tabKey,
        type: 'discount',
        id: discount.id,
        title: discount.title,
      });
    }
    tabsState.activeKey = tabKey;
    state.activeDiscount = discount;
    state.editingDiscountId = null; // Сначала показываем инфо, не редактор
    renderTabs();
    updateRightPanel();

    // Загружаем полные данные скидки с товарами и клиентами
    try {
      const json = await apiJson(`/api/admin/discounts/${discount.id}`);
      if (json.discount) {
        state.activeDiscount = json.discount;
        renderDiscountInfo(json.discount);
      } else {
        renderDiscountInfo(discount);
      }
    } catch (e) {
      console.error('openDiscountTab load error:', e);
      renderDiscountInfo(discount);
    }
  }

  // Открыть редактор скидки
  async function openDiscountEditor(discountId) {
    const isNew = !discountId;
    if (!isNew) {
      const existingDiscount = state.discounts.find((item) => Number(item?.id || 0) === Number(discountId || 0));
      if (isDeletedDiscount(existingDiscount)) {
        alert('Удаленную акцию сначала восстановите');
        return;
      }
    }
    const tabKey = isNew ? buildTabKey('discount', 'new') : buildTabKey('discount', discountId);

    let existing = tabsState.tabs.find(t => t.key === tabKey);
    if (!existing) {
      tabsState.tabs.push({
        key: tabKey,
        type: 'discount',
        id: discountId || 'new',
        title: isNew ? 'Новая скидка' : 'Редактирование',
      });
    }
    tabsState.activeKey = tabKey;
    state.editingDiscountId = discountId || 'new';

    // Заполняем форму
    if (elDiscountEditorForm) {
      if (isNew) {
        elDiscountEditorForm.reset();
        $('#de_id').value = '';
        $('#de_is_active').checked = true;
        $('#de_is_stackable').checked = false;
        $('#de_priority').value = '0';
        // Сброс выбранных товаров/клиентов
        state.discountSelectedProducts = [];
        state.discountSelectedCustomers = [];
        renderDiscountProductChips();
        renderDiscountCustomerChips();
      } else {
        // Загружаем полные данные скидки с сервера (включая products и customers)
        try {
          const json = await apiJson(`/api/admin/discounts/${discountId}`);
          if (json.discount) {
            fillDiscountForm(json.discount);
          }
        } catch (e) {
          console.error('openDiscountEditor load error:', e);
          // Fallback к локальным данным
          const discount = state.discounts.find(d => d.id === discountId);
          if (discount) {
            fillDiscountForm(discount);
          }
        }
      }
    }

    // Показать кнопку удаления только для существующих
    if (elDiscountDeleteBtn) {
      elDiscountDeleteBtn.style.display = isNew ? 'none' : '';
    }

    renderTabs();
    updateRightPanel();
  }

  // Заполнить форму скидки данными
  function fillDiscountForm(discount) {
    if (!elDiscountEditorForm) return;

    $('#de_id').value = discount.id || '';
    $('#de_title').value = discount.title || '';
    $('#de_discount_type').value = discount.discount_type || 'percent';
    $('#de_discount_value').value = discount.discount_value || '';
    $('#de_apply_to').value = discount.apply_to || 'order';
    $('#de_min_order_amount').value = discount.min_order_amount || '';
    $('#de_max_discount_amount').value = discount.max_discount_amount || '';

    // Даты
    if (discount.starts_at) {
      $('#de_starts_at').value = formatDateTimeLocal(discount.starts_at);
    } else {
      $('#de_starts_at').value = '';
    }
    if (discount.ends_at) {
      $('#de_ends_at').value = formatDateTimeLocal(discount.ends_at);
    } else {
      $('#de_ends_at').value = '';
    }

    // Расписание дней
    const scheduleDays = discount.schedule_days ? (typeof discount.schedule_days === 'string' ? JSON.parse(discount.schedule_days) : discount.schedule_days) : [];
    $$('#de_schedule_days input[type="checkbox"]').forEach(cb => {
      cb.checked = scheduleDays.includes(parseInt(cb.value, 10));
    });

    $('#de_schedule_time_start').value = discount.schedule_time_start || '';
    $('#de_schedule_time_end').value = discount.schedule_time_end || '';
    $('#de_usage_limit').value = discount.usage_limit || '';
    $('#de_usage_per_customer').value = discount.usage_per_customer || '';
    $('#de_priority').value = discount.priority || '0';
    $('#de_is_stackable').checked = !!discount.is_stackable;
    $('#de_is_active').checked = discount.is_active !== false && discount.is_active !== 0;

    // Загружаем выбранные товары
    if (Array.isArray(discount.products)) {
      state.discountSelectedProducts = discount.products.map(p => ({
        type: p.entity_type || 'product',
        id: p.entity_id,
        title: p.title || `#${p.entity_id}`
      }));
    } else {
      state.discountSelectedProducts = [];
    }
    renderDiscountProductChips();

    // Загружаем выбранных клиентов
    if (Array.isArray(discount.customers)) {
      state.discountSelectedCustomers = discount.customers.map(c => ({
        type: c.entity_type || 'customer',
        id: c.entity_id,
        title: c.title || `#${c.entity_id}`
      }));
    } else {
      state.discountSelectedCustomers = [];
    }
    renderDiscountCustomerChips();
  }

  // Форматировать дату для input datetime-local
  function formatDateTimeLocal(dateStr) {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return '';
    return d.toISOString().slice(0, 16);
  }

  // Загрузить заказы, где использовалась скидка
  async function loadDiscountOrders(discountId) {
    try {
      const json = await apiJson(`/api/admin/discounts/${discountId}/orders`);
      state.discountOrders = json.orders || [];
      renderDiscountOrders();
    } catch (err) {
      console.error('loadDiscountOrders error:', err);
      state.discountOrders = [];
    }
  }

  // Отрисовать заказы со скидкой в центральной колонке
    function renderDiscountOrders() {
    if (!elDiscountsList) return;

    // Если активна скидка, показываем её заказы
    if (!state.activeDiscount) {
      renderDiscountsList();
      return;
    }

    elDiscountsList.innerHTML = '';

    if (!state.discountOrders.length) {
      elDiscountsList.innerHTML = '<div class="empty-hint">Нет заказов с этой скидкой</div>';
      return;
    }

    state.discountOrders.forEach((order) => {
      const row = document.createElement('div');
      row.className = 'order-row discount-order-row';

      const date = order.used_at ? new Date(order.used_at).toLocaleString('ru') : '—';
      const total = order.total_price ? `${order.total_price}₽` : '—';
      const discountAmount = order.discount_amount ? `-${order.discount_amount}₽` : '';

      row.innerHTML = `
        <div class="order-row-info">
          <div class="order-row-title">${escapeHtml(order.customer_name || order.customer_phone || 'Без имени')}</div>
          <div class="order-row-meta">${date}</div>
        </div>
        <div class="order-row-right">
          <div class="order-row-total">${total}</div>
          <div class="order-row-discount">${discountAmount}</div>
        </div>
      `;

      elDiscountsList.appendChild(row);
    });
  }

  // Сохранить скидку
  async function saveDiscount() {
    if (!elDiscountEditorForm) return;

    const id = $('#de_id').value;
    const isNew = !id || id === 'new';

    // Собираем данные формы
    const scheduleDays = [];
    $$('#de_schedule_days input[type="checkbox"]:checked').forEach(cb => {
      scheduleDays.push(parseInt(cb.value, 10));
    });

    const data = {
      title: $('#de_title').value.trim(),
      discount_type: $('#de_discount_type').value,
      discount_value: parseFloat($('#de_discount_value').value) || 0,
      apply_to: $('#de_apply_to').value,
      min_order_amount: parseFloat($('#de_min_order_amount').value) || null,
      max_discount_amount: parseFloat($('#de_max_discount_amount').value) || null,
      starts_at: $('#de_starts_at').value || null,
      ends_at: $('#de_ends_at').value || null,
      schedule_days: scheduleDays.length ? scheduleDays : null,
      schedule_time_start: $('#de_schedule_time_start').value || null,
      schedule_time_end: $('#de_schedule_time_end').value || null,
      usage_limit: parseInt($('#de_usage_limit').value, 10) || null,
      usage_per_customer: parseInt($('#de_usage_per_customer').value, 10) || null,
      priority: parseInt($('#de_priority').value, 10) || 0,
      is_stackable: $('#de_is_stackable').checked,
      is_active: $('#de_is_active').checked,
      // Товары и клиенты
      products: state.discountSelectedProducts.map(p => ({
        entity_type: p.type,
        entity_id: p.id
      })),
      customers: state.discountSelectedCustomers.map(c => ({
        entity_type: c.type,
        entity_id: c.id
      })),
    };

    if (!data.title) {
      alert('Введите название скидки');
      return;
    }
    if (!data.discount_value || data.discount_value <= 0) {
      alert('Введите корректное значение скидки');
      return;
    }

    try {
      if (isNew) {
        await apiJson('/api/admin/discounts', { method: 'POST', body: data });
      } else {
        await apiJson(`/api/admin/discounts/${id}`, { method: 'PUT', body: data });
      }

      // Перезагружаем список скидок
      await loadDiscounts();

      // Закрываем таб
      closeActiveTab();

      state.editingDiscountId = null;
      updateRightPanel();
    } catch (err) {
      console.error('saveDiscount error:', err);
      alert('Ошибка сохранения: ' + err.message);
    }
  }

  function resetTwoStepButton(btn) {
    if (!btn) return;
    btn.classList.remove("is-confirm");
    if (btn.dataset.originalHtml != null) {
      btn.innerHTML = btn.dataset.originalHtml;
    }
    if (btn.dataset.originalTitle != null) {
      btn.title = btn.dataset.originalTitle;
    }
    if (btn.dataset.originalAria != null) {
      btn.setAttribute("aria-label", btn.dataset.originalAria);
    }
    if (btn.__twoStepTimer) {
      clearTimeout(btn.__twoStepTimer);
      btn.__twoStepTimer = null;
    }
    btn.__twoStepArmed = false;
  }

  function attachTwoStepButton(btn, onConfirm, confirmText = "Удалить") {
    if (!btn || btn.__twoStepBound) return;
    btn.__twoStepBound = true;
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (btn.disabled) return;
      if (btn.__twoStepArmed) {
        resetTwoStepButton(btn);
        onConfirm?.();
        return;
      }
      btn.__twoStepArmed = true;
      btn.classList.add("is-confirm");
      if (btn.dataset.originalHtml == null) btn.dataset.originalHtml = btn.innerHTML;
      if (btn.dataset.originalTitle == null) btn.dataset.originalTitle = btn.title || "";
      if (btn.dataset.originalAria == null) btn.dataset.originalAria = btn.getAttribute("aria-label") || "";
      btn.textContent = confirmText;
      if (btn.__twoStepTimer) clearTimeout(btn.__twoStepTimer);
      btn.__twoStepTimer = setTimeout(() => resetTwoStepButton(btn), 4000);
    });
  }

  function resetDiscountDeleteButtons() {
    resetTwoStepButton(elDiscountDeleteBtn);
    resetTwoStepButton(elDiscountInfoDeleteBtn);
  }

  async function closeDiscountTabs(discountId) {
    const normalizedDiscountId = Number(discountId || 0);
    if (!(normalizedDiscountId > 0)) return;
    const keys = tabsState.tabs
      .filter((tab) => (
        (tab?.type === "discount" && Number(tab?.id || 0) === normalizedDiscountId)
        || (tab?.type === "discount-promo-code" && Number(tab?.parentDiscountId || 0) === normalizedDiscountId)
      ))
      .map((tab) => tab.key);
    for (const key of keys) {
      await closeTab(key);
    }
  }

  async function focusDeletedDiscount(discountId) {
    const deletedDiscount = state.discounts.find((discount) => (
      Number(discount?.id || 0) === Number(discountId || 0) && isDeletedDiscount(discount)
    )) || null;
    state.activeDiscountFilter = "deleted";
    state.activeDiscountTypeFilter = "deleted";
    state.discountCenterMode = "list";
    syncDiscountToolbarState();
    renderDiscountFilters();
    if (deletedDiscount) {
      await openDiscountTab(deletedDiscount);
      return;
    }
    state.activeDiscountId = null;
    state.activeDiscount = null;
    updateRightPanel();
    renderDiscountsList();
  }

  async function restoreDiscount(discountIdValue = null) {
    const discountId = Number(discountIdValue || state.activeDiscountId || 0);
    if (!(discountId > 0)) return;
    try {
      await apiJson(`/api/admin/discounts/${discountId}/restore`, { method: "POST" });
      await loadDiscounts();
      state.activeDiscountFilter = "all";
      state.activeDiscountTypeFilter = "all";
      state.discountCenterMode = "list";
      resetDiscountDeleteButtons();
      const restoredDiscount = state.discounts.find((discount) => Number(discount?.id || 0) === discountId) || null;
      if (restoredDiscount) {
        await openDiscountTab(restoredDiscount);
      } else {
        await closeDiscountTabs(discountId);
        renderDiscountFilters();
        renderDiscountsList();
        updateRightPanel();
      }
    } catch (err) {
      console.error("restoreDiscount error:", err);
      alert("Ошибка восстановления: " + err.message);
    }
  }

  async function deleteDiscount(options = {}) {
    const rawOptions = options && typeof options === "object" && !("target" in options)
      ? options
      : {};
    const discountId = Number(
      rawOptions.discountId
      || state.activeDiscountId
      || $("#de_id")?.value
      || 0
    );
    if (!(discountId > 0)) return;

    const focusDeletedAfterDelete = rawOptions.focusDeletedAfterDelete === true;
    const shouldCloseTabs = rawOptions.closeTabs !== false && !focusDeletedAfterDelete;

    try {
      await apiJson(`/api/admin/discounts/${discountId}`, { method: "DELETE" });
      resetDiscountDeleteButtons();
      await loadDiscounts();

      if (focusDeletedAfterDelete) {
        await focusDeletedDiscount(discountId);
        return;
      }

      if (shouldCloseTabs) {
        await closeDiscountTabs(discountId);
      }

      if (Number(state.activeDiscountId || 0) === discountId) {
        state.activeDiscountId = null;
        state.activeDiscount = null;
        state.discountCenterMode = "list";
      }

      renderDiscountFilters();
      renderDiscountsList();
      updateRightPanel();
    } catch (err) {
      console.error("deleteDiscount error:", err);
      alert("Ошибка удаления: " + err.message);
    }
  }

  function renderDiscountsList() {
    if (!elDiscountsList) return;
    elDiscountsList.innerHTML = '';

    if (!state.discounts.length) {
      if (elDiscountsEmptyHint) elDiscountsEmptyHint.classList.remove('hidden');
      return;
    }
    if (elDiscountsEmptyHint) elDiscountsEmptyHint.classList.add('hidden');

    state.discounts.forEach((discount) => {
      const row = document.createElement('div');
      row.className = 'discount-row';
      row.classList.toggle('is-active', state.activeDiscountId === discount.id);

      const valueText = formatDiscountValue(discount);
      const applyToText = formatDiscountApplyToText(discount.apply_to);
      const activationText = formatDiscountActivationText(discount.activation_mode);

      row.innerHTML = `
        <div class="discount-row-icon"><i class="fas fa-percentage"></i></div>
        <div class="discount-row-info">
          <div class="discount-row-title">${escapeHtml(discount.title)}</div>
          <div class="discount-row-meta">${applyToText} • ${activationText} • ${discount.usage_count || 0} использований</div>
        </div>
        <div class="discount-row-value">${valueText}</div>
        <div class="discount-row-status ${discount.is_active ? '' : 'inactive'}"></div>
      `;

      row.addEventListener('click', () => {
        state.activeDiscountId = discount.id;
        openDiscountTab(discount);
        renderDiscountsList();
        renderDiscountFilters();
      });

      elDiscountsList.appendChild(row);
    });
  }

  async function openDiscountEditor(discountId) {
    const isNew = !discountId;
    if (!isNew) {
      const existingDiscount = state.discounts.find((item) => Number(item?.id || 0) === Number(discountId || 0));
      if (isDeletedDiscount(existingDiscount)) {
        alert('Удаленную акцию сначала восстановите');
        return;
      }
    }
    const tabKey = isNew ? buildTabKey('discount', 'new') : buildTabKey('discount', discountId);

    let existing = tabsState.tabs.find((t) => t.key === tabKey);
    if (!existing) {
      tabsState.tabs.push({
        key: tabKey,
        type: 'discount',
        id: discountId || 'new',
        title: isNew ? 'Новая скидка' : 'Редактирование',
      });
    }
    tabsState.activeKey = tabKey;
    state.editingDiscountId = discountId || 'new';
    state.discountPromoCodes = [];
    resetDiscountDeleteButtons();

    if (elDiscountEditorForm) {
      if (isNew) {
        elDiscountEditorForm.reset();
        $('#de_id').value = '';
        $('#de_is_active').checked = true;
        $('#de_is_stackable').checked = false;
        $('#de_priority').value = '0';
        if (elDeActivationMode) elDeActivationMode.value = 'auto';
        if (elDePromoCodeMode) elDePromoCodeMode.value = 'shared';
        if (elDePromoUniqueUsageLimit) elDePromoUniqueUsageLimit.value = '1';
        if (elDePromoGenerateCount) elDePromoGenerateCount.value = '10';
        if (elDePromoSharedCode) elDePromoSharedCode.value = '';
        if (elDePromoSharedUsageLimit) elDePromoSharedUsageLimit.value = '';
        state.discountSelectedProducts = [];
        state.discountSelectedCustomers = [];
        renderDiscountProductChips();
        renderDiscountCustomerChips();
        renderDiscountPromoCodes();
        updateDiscountPromoUi();
      } else {
        try {
          const json = await apiJson(`/api/admin/discounts/${discountId}`);
          if (json.discount) {
            state.activeDiscount = json.discount;
            fillDiscountForm(json.discount);
            const promo = getDiscountPromoFromDiscount(json.discount);
            if (promo.enabled && promo.code_mode === 'unique') {
              await loadDiscountPromoCodes(discountId);
            } else {
              state.discountPromoCodes = [];
              renderDiscountPromoCodes();
            }
            updateDiscountPromoUi();
          }
        } catch (e) {
          console.error('openDiscountEditor load error:', e);
          const discount = state.discounts.find((d) => d.id === discountId);
          if (discount) {
            fillDiscountForm(discount);
          }
        }
      }
    }

    if (elDiscountDeleteBtn) {
      elDiscountDeleteBtn.style.display = isNew ? 'none' : '';
    }

    renderTabs();
    updateRightPanel();
  }

  function fillDiscountForm(discount) {
    if (!elDiscountEditorForm) return;

    $('#de_id').value = discount.id || '';
    $('#de_title').value = discount.title || '';
    $('#de_discount_type').value = discount.discount_type || 'percent';
    $('#de_discount_value').value = discount.discount_value || '';
    $('#de_apply_to').value = discount.apply_to || 'order';
    $('#de_min_order_amount').value = discount.min_order_amount || '';
    $('#de_max_discount_amount').value = discount.max_discount_amount || '';

    $('#de_starts_at').value = discount.starts_at ? formatDateTimeLocal(discount.starts_at) : '';
    $('#de_ends_at').value = discount.ends_at ? formatDateTimeLocal(discount.ends_at) : '';

    let scheduleDays = [];
    if (Array.isArray(discount.schedule_days)) {
      scheduleDays = discount.schedule_days;
    } else if (typeof discount.schedule_days === 'string') {
      try {
        scheduleDays = JSON.parse(discount.schedule_days);
      } catch {
        scheduleDays = [];
      }
    }
    $$('#de_schedule_days input[type="checkbox"]').forEach((cb) => {
      cb.checked = scheduleDays.includes(parseInt(cb.value, 10));
    });

    $('#de_schedule_time_start').value = discount.schedule_time_start || '';
    $('#de_schedule_time_end').value = discount.schedule_time_end || '';
    $('#de_usage_limit').value = discount.usage_limit || '';
    $('#de_usage_per_customer').value = discount.usage_per_customer || '';
    $('#de_priority').value = discount.priority || '0';
    $('#de_is_stackable').checked = !!discount.is_stackable;
    $('#de_is_active').checked = discount.is_active !== false && discount.is_active !== 0;

    const promo = getDiscountPromoFromDiscount(discount);
    if (elDeActivationMode) elDeActivationMode.value = promo.activation_mode;
    if (elDePromoCodeMode) elDePromoCodeMode.value = promo.code_mode;
    if (elDePromoSharedCode) elDePromoSharedCode.value = promo.shared_code || '';
    if (elDePromoSharedUsageLimit) elDePromoSharedUsageLimit.value = promo.shared_code_usage_limit ?? '';
    if (elDePromoUniqueUsageLimit) elDePromoUniqueUsageLimit.value = promo.code_mode === 'unique' ? (promo.unique_code_usage_limit ?? '') : '';
    if (elDePromoGenerateCount) elDePromoGenerateCount.value = '';

    if (Array.isArray(discount.products)) {
      state.discountSelectedProducts = discount.products.map((p) => ({
        type: p.entity_type || 'product',
        id: p.entity_id,
        title: p.title || `#${p.entity_id}`,
      }));
    } else {
      state.discountSelectedProducts = [];
    }
    renderDiscountProductChips();

    if (Array.isArray(discount.customers)) {
      state.discountSelectedCustomers = discount.customers.map((c) => ({
        type: c.entity_type || 'customer',
        id: c.entity_id,
        title: c.title || `#${c.entity_id}`,
      }));
    } else {
      state.discountSelectedCustomers = [];
    }
    renderDiscountCustomerChips();

    state.discountPromoCodes = [];
    renderDiscountPromoCodes();
    updateDiscountPromoUi();
  }

  async function saveDiscount() {
    if (!elDiscountEditorForm) return;

    const id = $('#de_id').value;
    const isNew = !id || id === 'new';
    const scheduleDays = [];
    $$('#de_schedule_days input[type="checkbox"]:checked').forEach((cb) => {
      scheduleDays.push(parseInt(cb.value, 10));
    });

    const activationMode = elDeActivationMode?.value || 'auto';
    const promoCodeMode = elDePromoCodeMode?.value || 'shared';
    const promoEnabled = activationMode === 'promo_code';
    const sharedCode = normalizePromoCodeInputValue(elDePromoSharedCode?.value);
    const sharedCodeUsageLimit = parseInt(elDePromoSharedUsageLimit?.value, 10) || null;
    const uniqueCodeUsageLimit = Math.max(1, parseInt(elDePromoUniqueUsageLimit?.value, 10) || 1);
    const audienceMode = getDiscountAudienceMode();
    const audienceCustomers = audienceMode === 'all'
      ? []
      : state.discountSelectedCustomers
          .filter((item) => (
            audienceMode === 'category'
              ? String(item?.type || '').trim() === 'category'
              : String(item?.type || '').trim() !== 'category'
          ))
          .map((c) => ({
            entity_type: c.type,
            entity_id: c.id,
          }));

    const data = {
      title: $('#de_title').value.trim(),
      discount_type: $('#de_discount_type').value,
      discount_value: parseFloat($('#de_discount_value').value) || 0,
      apply_to: $('#de_apply_to').value,
      min_order_amount: parseFloat($('#de_min_order_amount').value) || null,
      max_discount_amount: parseFloat($('#de_max_discount_amount').value) || null,
      starts_at: $('#de_starts_at').value || null,
      ends_at: $('#de_ends_at').value || null,
      schedule_days: scheduleDays.length ? scheduleDays : null,
      schedule_time_start: $('#de_schedule_time_start').value || null,
      schedule_time_end: $('#de_schedule_time_end').value || null,
      usage_limit: parseInt($('#de_usage_limit').value, 10) || null,
      usage_per_customer: parseInt($('#de_usage_per_customer').value, 10) || null,
      priority: parseInt($('#de_priority').value, 10) || 0,
      is_stackable: $('#de_is_stackable').checked,
      is_active: $('#de_is_active').checked,
      activation_mode: activationMode,
      reward_type: 'discount',
      promo: {
        enabled: promoEnabled,
        code_mode: promoCodeMode,
        shared_code: sharedCode,
        shared_code_usage_limit: sharedCodeUsageLimit,
        unique_code_usage_limit: uniqueCodeUsageLimit,
      },
      products: state.discountSelectedProducts.map((p) => ({
        entity_type: p.type,
        entity_id: p.id,
      })),
      customers: state.discountSelectedCustomers.map((c) => ({
        entity_type: c.type,
        entity_id: c.id,
      })),
    };

    if (!data.title) {
      alert('Введите название скидки');
      return;
    }
    if (!data.discount_value || data.discount_value <= 0) {
      alert('Введите корректное значение скидки');
      return;
    }
    if (promoEnabled && promoCodeMode === 'shared' && !sharedCode) {
      alert('Введите промокод');
      return;
    }

    try {
      const response = isNew
        ? await apiJson('/api/admin/discounts', { method: 'POST', body: data })
        : await apiJson(`/api/admin/discounts/${id}`, { method: 'PUT', body: data });

      await loadDiscounts();

      if (isNew && promoEnabled && promoCodeMode === 'unique' && Number(response?.id || 0) > 0) {
        const createdId = Number(response.id);
        await closeTab(buildTabKey('discount', 'new'));
        state.activeDiscountId = createdId;
        renderDiscountFilters();
        renderDiscountsList();
        await openDiscountEditor(createdId);
        return;
      }

      closeActiveTab();
      state.editingDiscountId = null;
      updateRightPanel();
    } catch (err) {
      console.error('saveDiscount error:', err);
      alert(formatDiscountSaveErrorMessage(err));
    }
  }

  // -----------------------------
  function getDiscountListIcon(discount) {
    const mechanicType = normalizeDiscountMechanicType(discount?.mechanic_type);
    if (mechanicType === 'buy_x_get_y') return 'fa-gift';
    if (mechanicType === 'loyalty_progress') return 'fa-chart-line';
    if (mechanicType === 'threshold') return 'fa-layer-group';
    return 'fa-percentage';
  }

  function renderDiscountsList() {
    if (!elDiscountsList) return;
    elDiscountsList.innerHTML = '';

    if (!state.discounts.length) {
      if (elDiscountsEmptyHint) elDiscountsEmptyHint.classList.remove('hidden');
      return;
    }
    if (elDiscountsEmptyHint) elDiscountsEmptyHint.classList.add('hidden');

    state.discounts.forEach((discount) => {
      const row = document.createElement('div');
      row.className = 'discount-row';
      row.classList.toggle('is-active', state.activeDiscountId === discount.id);

      const promo = getDiscountPromoFromDiscount(discount);
      const mechanic = getDiscountMechanic(discount);
      const mechanicText = formatDiscountMechanicText(discount);
      const promoText = promo.enabled ? (promo.code_mode === 'unique' ? 'Уникальные коды' : 'Промокод') : 'Авто';

      row.innerHTML = `
        <div class="discount-row-icon"><i class="fas ${getDiscountListIcon(discount)}"></i></div>
        <div class="discount-row-info">
          <div class="discount-row-title">${escapeHtml(discount.title)}</div>
          <div class="discount-row-meta">${mechanicText} • ${promoText} • ${discount.usage_count || 0} использований</div>
        </div>
        <div class="discount-row-value">${formatDiscountValue(discount)}</div>
        <div class="discount-row-status ${discount.is_active ? '' : 'inactive'}"></div>
      `;

      row.addEventListener('click', () => {
        state.activeDiscountId = discount.id;
        openDiscountTab(discount);
        renderDiscountsList();
        renderDiscountFilters();
      });

      elDiscountsList.appendChild(row);
    });
  }

